INSERT INTO s VALUES
('S0000','v2_supp_09_physique.sql',9,'Qu''est-ce que le Système International d''unités (SI) et combien d''unités de base contient-il ?','Un système de mesure universel','Un système de mesure universel comportant 7 unités fondamentales : mètre, kilogramme, seconde, ampère, kelvin, mole, candela'),
('S0001','v2_supp_09_physique.sql',9,'Qu''est-ce que l''incertitude de mesure et comment l''exprime-t-on ?','La plage de valeurs dans laquelle la','La plage de valeurs dans laquelle la grandeur réelle se situe probablement, exprimée comme valeur ± incertitude (ex. 9,81 ± 0,02 m/s²)'),
('S0002','v2_supp_09_physique.sql',9,'Qu''est-ce que l''analyse dimensionnelle en physique ?','La vérification de la cohérence des','La vérification de la cohérence des équations en s''assurant que les dimensions des deux membres sont identiques (ex. vérifier que F=ma a bien des dimensions de force)'),
('S0003','v2_supp_09_physique.sql',9,'Qu''est-ce que la notation scientifique et comment l''utilise-t-on en physique ?','L''écriture d''un nombre sous la forme a','L''écriture d''un nombre sous la forme a × 10ⁿ (1 ≤ a < 10) permettant d''exprimer de très grands ou petits nombres : ex. vitesse de la lumière c = 3,0 × 10⁸ m/s'),
('S0004','v2_supp_09_physique.sql',9,'Quelle est la différence entre une grandeur scalaire et une grandeur vectorielle ?','Un scalaire est défini par sa seule','Un scalaire est défini par sa seule valeur numérique (température, masse) ; un vecteur a une valeur, une direction et un sens (force, vitesse)'),
('S0005','v2_supp_09_physique.sql',9,'Qu''est-ce que l''ordre de grandeur en physique et pourquoi est-il utile ?','L''estimation à la puissance de dix près','L''estimation à la puissance de dix près de la valeur d''une grandeur physique, permettant de vérifier rapidement si un résultat est raisonnable'),
('S0006','v2_supp_09_physique.sql',9,'Qu''est-ce que la conversion d''unités et comment réalise-t-on un changement d''unités correctement ?','On multiplie par le facteur de','On multiplie par le facteur de conversion approprié (ex. 1 km = 1000 m → 5 km = 5 × 1000 m = 5000 m) en faisant attention aux puissances'),
('S0007','v2_supp_09_physique.sql',9,'Quels sont les principaux instruments de mesure en physique et leur grandeur mesurée ?','Multimètre (courant/tension)','Multimètre (courant/tension), thermomètre (température), manomètre (pression), balance (masse), chronomètre (temps), oscilloscope (tensions variables)'),
('S0008','v2_supp_09_physique.sql',9,'Qu''est-ce que la précision et l''exactitude en métrologie et comment les distingue-t-on ?','La précision = capacité à reproduire la','La précision = capacité à reproduire la même valeur (faible dispersion) ; l''exactitude = proximité à la valeur vraie ; un instrument peut être précis sans être exact'),
('S0009','v2_supp_09_physique.sql',9,'Quelle est la valeur de g (accélération gravitationnelle à la surface de la Terre) et comment varie-t-elle ?','g ≈ 9,81 m/s² à la surface de la Terre','g ≈ 9,81 m/s² à la surface de la Terre (arrondi à 10 m/s² en physique scolaire) ; elle varie légèrement avec la latitude et l''altitude'),
('S0010','v2_supp_09_physique.sql',9,'Qu''est-ce que la vitesse moyenne et comment se calcule-t-elle ?','Le rapport de la distance parcourue sur','Le rapport de la distance parcourue sur la durée du trajet : v_moy = d/Δt (en m/s)'),
('S0011','v2_supp_09_physique.sql',9,'Qu''est-ce que l''accélération et quelle est son unité SI ?','La variation de la vitesse par unité de','La variation de la vitesse par unité de temps : a = Δv/Δt, exprimée en m/s² (mètre par seconde au carré)'),
('S0012','v2_supp_09_physique.sql',9,'Pour un mouvement uniformément accéléré (MRUA), quelle est l''équation de la vitesse en fonction du temps ?','v(t) = v₀ + a·t','v(t) = v₀ + a·t, où v₀ est la vitesse initiale, a l''accélération constante et t le temps'),
('S0013','v2_supp_09_physique.sql',9,'Qu''est-ce que le mouvement circulaire uniforme (MCU) et quelle est son accélération ?','Un mouvement sur un cercle à vitesse','Un mouvement sur un cercle à vitesse constante, avec une accélération centripète a_c = v²/r dirigée vers le centre'),
('S0014','v2_supp_09_physique.sql',9,'Qu''est-ce que la trajectoire parabolique d''un projectile (tir oblique) ?','La trajectoire courbe d''un objet lancé','La trajectoire courbe d''un objet lancé avec une composante horizontale et soumis uniquement à la gravité : mouvement rectiligne uniforme en x et uniformément accéléré en y'),
('S0015','v2_supp_09_physique.sql',9,'Qu''est-ce que la chute libre et quelles en sont les équations ?','La chute d''un objet en l''absence de','La chute d''un objet en l''absence de résistance de l''air sous l''effet seul de la gravité g ; équations : v = g·t, h = ½g·t², v² = 2g·h'),
('S0016','v2_supp_09_physique.sql',9,'Comment représente-t-on graphiquement un mouvement rectiligne uniforme (MRU) ?','Par une droite sur le graphique','Par une droite sur le graphique position-temps (x = v·t) et une droite horizontale sur le graphique vitesse-temps (v = constante)'),
('S0017','v2_supp_09_physique.sql',9,'Qu''est-ce que la période et la fréquence dans un mouvement circulaire ou oscillatoire ?','La période T est le temps pour','La période T est le temps pour compléter un cycle (en secondes) ; la fréquence f = 1/T est le nombre de cycles par seconde (en Hz = s⁻¹)'),
('S0018','v2_supp_09_physique.sql',9,'Qu''est-ce que le vecteur déplacement et comment diffère-t-il de la distance parcourue ?','Le déplacement est un vecteur entre','Le déplacement est un vecteur entre position initiale et finale (indépendant du chemin) ; la distance est la longueur totale du trajet parcouru'),
('S0019','v2_supp_09_physique.sql',9,'Quelle est la première loi de Newton (loi d''inertie) ?','Tout corps persévère dans son état de','Tout corps persévère dans son état de repos ou de mouvement rectiligne uniforme tant qu''aucune force extérieure ne l''en écarte'),
('S0020','v2_supp_09_physique.sql',9,'Quelle est la deuxième loi de Newton et quelle est sa formule ?','ΣF = m·a','ΣF = m·a : la résultante des forces appliquées à un objet est égale au produit de sa masse par son accélération'),
('S0021','v2_supp_09_physique.sql',9,'Quelle est la troisième loi de Newton (loi des actions réciproques) ?','Lorsque A exerce une force sur B','Lorsque A exerce une force sur B, B exerce simultanément sur A une force égale en magnitude et opposée en sens : F_AB = -F_BA'),
('S0022','v2_supp_09_physique.sql',9,'Qu''est-ce que la force de frottement et comment l''exprime-t-on ?','Une force de contact s''opposant au','Une force de contact s''opposant au mouvement ou à la tendance au mouvement, proportionnelle à la force normale : f = μN, où μ est le coefficient de frottement'),
('S0023','v2_supp_09_physique.sql',9,'Qu''est-ce que le poids et comment diffère-t-il de la masse ?','La masse m est une propriété','La masse m est une propriété intrinsèque de la matière (en kg) ; le poids P = m·g est la force gravitationnelle exercée sur l''objet (en N) ; la masse est la même partout, le poids varie selon g'),
('S0024','v2_supp_09_physique.sql',9,'Qu''est-ce que la loi de la gravitation universelle de Newton ?','La force attractive entre deux masses','La force attractive entre deux masses m₁ et m₂ séparées d''une distance r : F = G·m₁·m₂/r², avec G = 6,674 × 10⁻¹¹ N·m²/kg²'),
('S0025','v2_supp_09_physique.sql',9,'Qu''est-ce que le travail d''une force en physique et comment le calcule-t-on ?','W = F·d·cosθ','W = F·d·cosθ : le travail d''une force est le produit de la force par le déplacement et le cosinus de l''angle entre eux ; il s''exprime en Joules (J)'),
('S0026','v2_supp_09_physique.sql',9,'Qu''est-ce que l''énergie cinétique et le théorème énergie-travail ?','Ec = ½mv²','Ec = ½mv² ; le théorème travail-énergie énonce que le travail total effectué sur un objet est égal à la variation de son énergie cinétique : W_total = ΔEc = Ecf - Eci'),
('S0027','v2_supp_09_physique.sql',9,'Qu''est-ce que la conservation de l''énergie mécanique ?','En l''absence de forces dissipatives','En l''absence de forces dissipatives (frottement), l''énergie mécanique totale Em = Ec + Ep se conserve : Em_i = Em_f'),
('S0028','v2_supp_09_physique.sql',9,'Qu''est-ce que la quantité de mouvement (impulsion) et sa conservation ?','p = m·v (vecteur)','p = m·v (vecteur) ; dans un système isolé, la quantité de mouvement totale se conserve (Σp_avant = Σp_après), principe fondamental pour analyser les collisions'),
('S0029','v2_supp_09_physique.sql',9,'Quelle est la loi d''Ohm et comment s''applique-t-elle ?','U = R·I','U = R·I : la tension aux bornes d''un conducteur ohmique est proportionnelle au courant qui le traverse, R étant la résistance en ohms (Ω)'),
('S0030','v2_supp_09_physique.sql',9,'Quelles sont les lois de Kirchhoff pour l''analyse des circuits électriques ?','Loi des nœuds (ΣI_entrant = ΣI_sortant)','Loi des nœuds (ΣI_entrant = ΣI_sortant) et loi des mailles (Σ(tensions) = 0 autour d''une maille fermée), permettant d''analyser tout circuit complexe'),
('S0031','v2_supp_09_physique.sql',9,'Comment calcule-t-on la résistance équivalente en série et en parallèle ?','En série : Req = R₁ + R₂ + ...','En série : Req = R₁ + R₂ + ... (Req > Ri) ; en parallèle : 1/Req = 1/R₁ + 1/R₂ + ... (Req < Req < Ri)'),
('S0032','v2_supp_09_physique.sql',9,'Qu''est-ce que la puissance électrique et son expression ?','P = U·I = R·I² = U²/R, exprimée en watts','P = U·I = R·I² = U²/R, exprimée en watts (W) ; l''énergie électrique consommée : E = P·t (en Joules ou kWh)'),
('S0033','v2_supp_09_physique.sql',9,'Qu''est-ce que le condensateur et sa capacité ?','Un composant stockant de l''énergie','Un composant stockant de l''énergie électrostatique sous forme de charges séparées : C = Q/U, exprimée en farads (F) ; l''énergie stockée : E = ½CU²'),
('S0034','v2_supp_09_physique.sql',9,'Qu''est-ce que la loi de Coulomb et la force électrostatique ?','La force entre deux charges q₁ et q₂','La force entre deux charges q₁ et q₂ séparées de r : F = k·q₁·q₂/r², avec k = 9×10⁹ N·m²/C² ; attractive si charges opposées, répulsive si charges identiques'),
('S0035','v2_supp_09_physique.sql',9,'Qu''est-ce que le courant alternatif (CA) et en quoi diffère-t-il du courant continu (CC) ?','Le CC circule dans un sens fixe (piles)','Le CC circule dans un sens fixe (piles) ; le CA change périodiquement de sens (réseau domestique), caractérisé par sa fréquence (60 Hz en Haïti) et sa valeur efficace (120 V en Haïti)'),
('S0036','v2_supp_09_physique.sql',9,'Qu''est-ce que le transformateur et quel est son principe de fonctionnement ?','Un dispositif à deux bobines couplées','Un dispositif à deux bobines couplées magnétiquement qui modifie la tension alternative : U₁/U₂ = N₁/N₂ (rapport de transformation proportionnel au nombre de spires)'),
('S0037','v2_supp_09_physique.sql',9,'Qu''est-ce que la mise à la terre (mise à la masse) dans une installation électrique ?','La connexion d''un conducteur de','La connexion d''un conducteur de protection à la terre (potentiel 0 V) pour dévier les courants de fuite et protéger les utilisateurs des électrocutions'),
('S0038','v2_supp_09_physique.sql',9,'Quelle est la vitesse de la lumière dans le vide et sa signification en physique ?','c = 3 × 10⁸ m/s','c = 3 × 10⁸ m/s, constante fondamentale de la physique (limite de vitesse universelle selon la relativité restreinte d''Einstein) ; elle détermine l''unité astronomique «année-lumière»'),
('S0039','v2_supp_09_physique.sql',9,'Qu''est-ce que la réfraction de la lumière et la loi de Snell-Descartes ?','Le changement de direction de la','Le changement de direction de la lumière lors du passage entre deux milieux de nature différente : n₁·sin(θ₁) = n₂·sin(θ₂), où n est l''indice de réfraction'),
('S0040','v2_supp_09_physique.sql',9,'Qu''est-ce que la réflexion totale interne et quelle est son application dans les fibres optiques ?','Lorsque la lumière passe d''un milieu','Lorsque la lumière passe d''un milieu dense vers un moins dense avec un angle supérieur à l''angle critique, elle est totalement réfléchie ; les fibres optiques utilisent ce principe pour transmettre des données sans perte'),
('S0041','v2_supp_09_physique.sql',9,'Qu''est-ce que la dispersion de la lumière et comment explique-t-elle l''arc-en-ciel ?','La décomposition de la lumière blanche','La décomposition de la lumière blanche en ses composantes spectrales (ROYGBIV) car l''indice de réfraction dépend de la longueur d''onde ; les gouttes d''eau dispersent la lumière solaire formant l''arc-en-ciel'),
('S0042','v2_supp_09_physique.sql',9,'Qu''est-ce que la nature duale de la lumière (onde-corpuscule) ?','La lumière se comporte comme une onde','La lumière se comporte comme une onde (interférence, diffraction) ET comme un ensemble de corpuscules (photons) selon l''expérience réalisée : dualité onde-corpuscule (fondement de la physique quantique)'),
('S0043','v2_supp_09_physique.sql',9,'Comment fonctionne une lentille convergente et où se forme l''image d''un objet ?','Elle concentre les rayons parallèles en','Elle concentre les rayons parallèles en un foyer F'' à distance focale f'' ; l''image se forme selon la relation de conjugaison : 1/OA'' - 1/OA = 1/f'' (convention algébrique)'),
('S0044','v2_supp_09_physique.sql',9,'Qu''est-ce que le spectre électromagnétique et quels types de rayonnements comprend-il ?','L''ensemble des ondes électromagnétiques','L''ensemble des ondes électromagnétiques classées par fréquence/longueur d''onde : ondes radio, micro-ondes, infrarouge, visible, UV, rayons X, rayons gamma'),
('S0045','v2_supp_09_physique.sql',9,'Qu''est-ce que la polarisation de la lumière et ses applications pratiques ?','La propriété de la lumière dont les','La propriété de la lumière dont les oscillations du champ électrique sont confinées dans un plan particulier ; applications : lunettes polarisantes, écrans LCD, mesure de concentration en chimie'),
('S0046','v2_supp_09_physique.sql',9,'Qu''est-ce que l''effet Doppler pour la lumière et ses applications en astronomie ?','Le décalage de fréquence d''une source','Le décalage de fréquence d''une source lumineuse se déplaçant par rapport à l''observateur : décalage vers le rouge (redshift) si la source s''éloigne ; utilisé pour mesurer les vitesses des galaxies'),
('S0047','v2_supp_09_physique.sql',9,'Quel est le premier principe de la thermodynamique et sa signification ?','La variation d''énergie interne d''un','La variation d''énergie interne d''un système fermé = chaleur reçue + travail reçu : ΔU = Q + W (conservation de l''énergie) ; l''énergie ne peut ni être créée ni détruite'),
('S0048','v2_supp_09_physique.sql',9,'Quel est le deuxième principe de la thermodynamique et la notion d''entropie ?','Dans un système isolé','Dans un système isolé, l''entropie (désordre) ne peut qu''augmenter ou rester constante (ΔS ≥ 0) ; la chaleur va spontanément du chaud vers le froid'),
('S0049','v2_supp_09_physique.sql',9,'Quels sont les trois modes de transfert thermique et leurs caractéristiques ?','Conduction (contact direct','Conduction (contact direct, solides), convection (mouvement de fluide, liquides/gaz) et rayonnement (ondes électromagnétiques, sans support matériel, propagation dans le vide)'),
('S0050','v2_supp_09_physique.sql',9,'Qu''est-ce que la chaleur latente et comment intervient-elle lors des changements d''état ?','L''énergie absorbée ou libérée lors d''un','L''énergie absorbée ou libérée lors d''un changement d''état (fusion, vaporisation) à température constante ; ex. : L_vap(eau) = 2257 kJ/kg à 100°C'),
('S0051','v2_supp_09_physique.sql',9,'Qu''est-ce que la capacité calorifique massique et la formule de la chaleur sensible ?','Q = m·c·ΔT','Q = m·c·ΔT : la chaleur échangée est le produit de la masse, de la capacité calorifique massique c (J/(kg·K)) et de la variation de température'),
('S0052','v2_supp_09_physique.sql',9,'Qu''est-ce que la loi des gaz parfaits (loi de Boyle-Mariotte, Gay-Lussac, Charles) ?','PV = nRT','PV = nRT : pour un gaz parfait, la pression P, le volume V, la quantité n (en moles) et la température T (en Kelvin) sont liés par la constante des gaz parfaits R = 8,314 J/(mol·K)'),
('S0053','v2_supp_09_physique.sql',9,'Qu''est-ce que le rendement d''un moteur thermique et la limite de Carnot ?','Le rendement η = W_utile / Q_absorbé ≤ 1','Le rendement η = W_utile / Q_absorbé ≤ 1 ; le rendement de Carnot η_max = 1 - T_froide/T_chaude (températures en Kelvin) est la limite théorique pour tout moteur thermique entre deux sources'),
('S0054','v2_supp_09_physique.sql',9,'Qu''est-ce que la radioactivité naturelle et quels sont ses types principaux ?','L''émission spontanée de rayonnements','L''émission spontanée de rayonnements par des noyaux instables ; types : α (noyaux d''hélium-4), β⁻ (électrons), β⁺ (positrons), γ (photons de haute énergie)'),
('S0055','v2_supp_09_physique.sql',9,'Qu''est-ce que la demi-vie radioactive (période) et comment l''utilise-t-on en datation ?','Le temps T₁/₂ après lequel la moitié','Le temps T₁/₂ après lequel la moitié des atomes radioactifs d''un échantillon s''est désintégrée ; N(t) = N₀·(1/2)^(t/T½) ; la datation au ¹⁴C (T½ = 5730 ans) date les matières organiques'),
('S0056','v2_supp_09_physique.sql',9,'Qu''est-ce que la fission nucléaire et comment est-elle utilisée dans les centrales ?','La division d''un noyau lourd','La division d''un noyau lourd (uranium-235, plutonium-239) en deux noyaux plus légers lors de l''absorption d''un neutron, libérant énergie et neutrons supplémentaires (réaction en chaîne)'),
('S0057','v2_supp_09_physique.sql',9,'Quelle est la relation énergie-masse d''Einstein et son application à la physique nucléaire ?','E = mc²','E = mc² : la masse m et l''énergie E sont équivalentes ; c = 3×10⁸ m/s ; c''est la conversion entre matière et énergie (défaut de masse = énergie libérée en fission/fusion)'),
('S0058','v2_supp_09_physique.sql',9,'Qu''est-ce que la fusion nucléaire et son intérêt énergétique ?','L''union de deux noyaux légers formant','L''union de deux noyaux légers (ex. deutérium + tritium) formant un noyau plus lourd en libérant beaucoup plus d''énergie que la fission, avec peu de déchets radioactifs ; c''est la source d''énergie du soleil'),
('S0059','v2_supp_09_physique.sql',9,'Qu''est-ce que le modèle quantique de l''atome et ses différences avec le modèle de Bohr ?','Le modèle quantique remplace les','Le modèle quantique remplace les orbites fixes de Bohr par des orbitales (régions de probabilité de présence de l''électron) décrites par la mécanique quantique (Schrödinger, 1926)'),
('S0060','v2_supp_09_physique.sql',9,'Qu''est-ce que le principe d''incertitude de Heisenberg et sa signification ?','Il est fondamentalement impossible de','Il est fondamentalement impossible de mesurer simultanément avec précision la position et la quantité de mouvement d''une particule : Δx·Δp ≥ ħ/2'),
('S0061','v2_supp_09_physique.sql',9,'Qu''est-ce que l''effet photoélectrique et comment Einstein l''a-t-il expliqué ?','L''émission d''électrons par un métal','L''émission d''électrons par un métal éclairé par une lumière de fréquence suffisante ; Einstein (1905) l''a expliqué en traitant la lumière comme des photons d''énergie E = hf, démontrant la quantification de la lumière'),
('S0062','v2_supp_09_physique.sql',9,'Quel est le rôle de la physique dans le développement durable et les énergies renouvelables ?','La physique sous-tend toutes les','La physique sous-tend toutes les technologies d''énergie renouvelable : panneaux photovoltaïques (effet photoélectrique), éoliennes (mécanique des fluides), géothermie (thermodynamique), stockage (supercondensateurs, batteries)'),
('S0063','v2_supp_10_chimie.sql',10,'Qui a proposé le tableau périodique des éléments et en quelle année ?','Dmitri Mendeleïev en 1869','Dmitri Mendeleïev en 1869, en classant les éléments par masse atomique croissante et en découvrant la périodicité des propriétés'),
('S0064','v2_supp_10_chimie.sql',10,'Qu''est-ce que le numéro atomique Z et le nombre de masse A d''un élément ?','Z est le nombre de protons dans le noyau','Z est le nombre de protons dans le noyau (caractérise l''élément) ; A = Z + N est la somme des protons et neutrons (nucléons)'),
('S0065','v2_supp_10_chimie.sql',10,'Qu''est-ce que la configuration électronique d''un atome et comment la détermine-t-on ?','La distribution des électrons dans les','La distribution des électrons dans les couches et sous-couches (1s, 2s, 2p, 3s, 3p, etc.) selon les règles de Aufbau, Pauli et Hund ; ex. sodium (Z=11) : 1s²2s²2p⁶3s¹'),
('S0066','v2_supp_10_chimie.sql',10,'Qu''est-ce que les électrons de valence et pourquoi sont-ils importants en chimie ?','Les électrons de la couche externe','Les électrons de la couche externe (couche de valence) qui participent aux liaisons chimiques ; leur nombre détermine la réactivité chimique et la valence'),
('S0067','v2_supp_10_chimie.sql',10,'Quelles sont les tendances générales de l''électronégativité dans le tableau périodique ?','L''électronégativité augmente de gauche','L''électronégativité augmente de gauche à droite dans une période et de bas en haut dans un groupe ; le fluor (F) est l''élément le plus électronégatif'),
('S0068','v2_supp_10_chimie.sql',10,'Qu''est-ce que les isotopes d''un élément et en quoi diffèrent-ils ?','Des atomes du même élément (même Z)','Des atomes du même élément (même Z) ayant des nombres de neutrons différents (donc des masses atomiques différentes) ; ex. ¹H, ²H (deutérium), ³H (tritium)'),
('S0069','v2_supp_10_chimie.sql',10,'Qu''est-ce qu''un ion et comment se forme-t-il ?','Un atome ou groupe d''atomes ayant perdu','Un atome ou groupe d''atomes ayant perdu ou gagné des électrons : cation (perte d''e⁻, charge positive) ou anion (gain d''e⁻, charge négative) ; ex. Na⁺ (Z=11, 10e⁻), Cl⁻ (Z=17, 18e⁻)'),
('S0070','v2_supp_10_chimie.sql',10,'Qu''est-ce que la différence entre un métal, un métalloïde et un non-métal dans le tableau périodique ?','Les métaux (à gauche) sont conducteurs','Les métaux (à gauche) sont conducteurs, malléables, brillants ; les non-métaux (à droite) sont isolants, souvent gazeux ; les métalloïdes (semi-conducteurs) sont à la frontière (Si, Ge, As)'),
('S0071','v2_supp_10_chimie.sql',10,'Qu''est-ce que la règle de l''octet et ses exceptions ?','La tendance des atomes à acquérir une','La tendance des atomes à acquérir une configuration de 8 électrons de valence (octets) lors des liaisons ; exceptions : H (2e⁻), BF₃ (6e⁻), PCl₅ (10e⁻)'),
('S0072','v2_supp_10_chimie.sql',10,'Qu''est-ce que l''énergie d''ionisation et ses tendances dans le tableau périodique ?','L''énergie nécessaire pour arracher un','L''énergie nécessaire pour arracher un électron à un atome à l''état gazeux ; elle augmente de gauche à droite et de bas en haut (tendances inverses de l''électronégativité)'),
('S0073','v2_supp_10_chimie.sql',10,'Quelle est la différence entre une liaison ionique et une liaison covalente ?','Liaison ionique','Liaison ionique : transfert d''électron(s) entre métal et non-métal formant des ions (NaCl) ; liaison covalente : partage d''électron(s) entre non-métaux (H₂O, CH₄)'),
('S0074','v2_supp_10_chimie.sql',10,'Qu''est-ce que la liaison hydrogène et son importance en chimie ?','Une liaison faible entre un H lié à un','Une liaison faible entre un H lié à un atome très électronégatif (N, O, F) et un autre atome électronégatif ; responsable de la tension de surface de l''eau, de la structure de l''ADN et des points d''ébullition élevés'),
('S0075','v2_supp_10_chimie.sql',10,'Qu''est-ce que la géométrie moléculaire selon la théorie VSEPR ?','La forme géométrique d''une molécule est','La forme géométrique d''une molécule est déterminée par la répulsion des paires d''électrons (liants et non-liants) autour de l''atome central ; ex. H₂O : angulaire (2 paires non-liantes), CH₄ : tétraédrique'),
('S0076','v2_supp_10_chimie.sql',10,'Qu''est-ce que la polarité d''une molécule et quels en sont les exemples ?','Une molécule est polaire si elle','Une molécule est polaire si elle possède un moment dipolaire net (liaisons polaires asymétriquement arrangées) ; ex. H₂O est polaire (V-shape) ; CO₂ est apolaire (linéaire, dipôles opposés)'),
('S0077','v2_supp_10_chimie.sql',10,'Qu''est-ce que la liaison métallique et comment explique-t-elle les propriétés des métaux ?','Un nuage d''électrons délocalisés autour','Un nuage d''électrons délocalisés autour d''un réseau d''ions positifs (cations métalliques) ; explique la conductivité électrique (e⁻ libres), la malléabilité (glissement des couches) et la brillance des métaux'),
('S0078','v2_supp_10_chimie.sql',10,'Qu''est-ce que la structure de Lewis d''une molécule et comment la dessiner ?','La représentation des liaisons et des','La représentation des liaisons et des paires d''électrons non-liants autour des atomes d''une molécule ; étapes : compter les électrons de valence, placer les liaisons, compléter les octets'),
('S0079','v2_supp_10_chimie.sql',10,'Qu''est-ce qu''une liaison covalente simple, double et triple et leurs caractéristiques ?','Liaison simple (σ','Liaison simple (σ, 1 paire partagée), double (σ + π, 2 paires), triple (σ + 2π, 3 paires) ; les liaisons multiples raccourcissent la liaison et augmentent son énergie : C-C < C=C < C≡C en longueur'),
('S0080','v2_supp_10_chimie.sql',10,'Qu''est-ce que la résonance en chimie et quand s''applique-t-elle ?','Lorsqu''une structure de Lewis unique ne','Lorsqu''une structure de Lewis unique ne représente pas bien une molécule et que la vraie structure est un hybride de plusieurs structures de résonance (ex. CO₃²⁻, benzène C₆H₆) : les électrons sont délocalisés'),
('S0081','v2_supp_10_chimie.sql',10,'Qu''est-ce que les interactions de Van der Waals et leur importance ?','Les forces intermoléculaires faibles','Les forces intermoléculaires faibles (London/dispersion, dipôle-dipôle, Keesom) résultant de fluctuations ou permanences de dipôles ; elles explique la cohésion des gaz nobles liquéfiés et des molécules apolaires'),
('S0082','v2_supp_10_chimie.sql',10,'Qu''est-ce que la stœchiométrie et la mole en chimie ?','L''étude quantitative des réactifs et','L''étude quantitative des réactifs et produits d''une réaction chimique ; la mole (n = m/M = N/Nₐ) est l''unité de quantité de matière contenant Nₐ = 6,022×10²³ entités'),
('S0083','v2_supp_10_chimie.sql',10,'Comment équilibre-t-on une équation chimique et quelle loi respecte-t-on ?','En ajustant les coefficients','En ajustant les coefficients stœchiométriques pour que le nombre d''atomes de chaque élément soit identique des deux côtés : loi de conservation de la masse (Lavoisier)'),
('S0084','v2_supp_10_chimie.sql',10,'Qu''est-ce qu''un réactif limitant dans une réaction chimique ?','Le réactif qui est entièrement consommé','Le réactif qui est entièrement consommé en premier, déterminant la quantité maximale de produit formé ; l''autre réactif est en excès'),
('S0085','v2_supp_10_chimie.sql',10,'Qu''est-ce que le rendement d''une réaction et comment le calcule-t-on ?','η = (quantité obtenue / quantité','η = (quantité obtenue / quantité théorique) × 100% ; les rendements < 100% s''expliquent par des réactions parasites, des pertes et des équilibres incomplets'),
('S0086','v2_supp_10_chimie.sql',10,'Qu''est-ce qu''une réaction d''oxydoréduction (redox) et ses composants ?','Une réaction avec transfert d''électrons','Une réaction avec transfert d''électrons : l''oxydant gagne des électrons (est réduit) et le réducteur perd des électrons (est oxydé) ; l''oxydation augmente le nombre d''oxydation, la réduction le diminue'),
('S0087','v2_supp_10_chimie.sql',10,'Qu''est-ce que la théorie acide-base de Brønsted-Lowry ?','Un acide de Brønsted-Lowry est un','Un acide de Brønsted-Lowry est un donneur de proton (H⁺) et une base est un accepteur de proton ; ex. HCl (acide) + H₂O (base) → H₃O⁺ + Cl⁻'),
('S0088','v2_supp_10_chimie.sql',10,'Qu''est-ce que le pH et comment se calcule-t-il ?','pH = -log[H₃O⁺]','pH = -log[H₃O⁺] ; pH < 7 = acide, pH = 7 = neutre, pH > 7 = basique ; une variation d''une unité de pH représente un facteur 10 de changement de concentration'),
('S0089','v2_supp_10_chimie.sql',10,'Qu''est-ce qu''un équilibre chimique et la constante d''équilibre K ?','L''état où les vitesses de la réaction','L''état où les vitesses de la réaction directe et inverse sont égales ; K = [produits]/[réactifs] (rapport à l''équilibre) ; K>>1 : réaction favorise les produits, K<<1 : réactifs favorisés'),
('S0090','v2_supp_10_chimie.sql',10,'Qu''est-ce que le principe de Le Chatelier et comment s''applique-t-il ?','Si on perturbe un système à l''équilibre','Si on perturbe un système à l''équilibre (concentration, pression, température), il se déplace pour s''opposer à la perturbation ; ex. augmenter la pression déplace vers le côté avec moins de moles de gaz'),
('S0091','v2_supp_10_chimie.sql',10,'Qu''est-ce que la cinétique chimique et les facteurs influençant la vitesse de réaction ?','L''étude de la vitesse des réactions','L''étude de la vitesse des réactions chimiques ; elle dépend de la concentration des réactifs, de la température (loi d''Arrhenius : vitesse double ~tous les 10°C), des catalyseurs et de l''état de la matière'),
('S0092','v2_supp_10_chimie.sql',10,'Qu''est-ce que la chimie organique et pourquoi le carbone est-il au cœur de cette chimie ?','L''étude des composés du carbone','L''étude des composés du carbone (sauf CO, CO₂, carbonates) ; le C est tétravalent, forme 4 liaisons covalentes, des chaînes et cycles, permettant une diversité quasi-infinie de molécules'),
('S0093','v2_supp_10_chimie.sql',10,'Quels sont les groupes fonctionnels principaux en chimie organique et leurs propriétés ?','Alcool (-OH)','Alcool (-OH), aldéhyde (-CHO), cétone (C=O), acide carboxylique (-COOH), amine (-NH₂), ester (-COO-) ; chaque groupe confère des propriétés chimiques spécifiques'),
('S0094','v2_supp_10_chimie.sql',10,'Qu''est-ce que l''isomérie en chimie organique et quels en sont les types ?','Des composés de même formule brute mais','Des composés de même formule brute mais de structures différentes : isomères constitutionnels (chaîne, position, fonction) et stéréoisomères (géométrique Z/E, optique R/S)'),
('S0095','v2_supp_10_chimie.sql',10,'Qu''est-ce que les réactions de substitution nucléophile (SN1/SN2) en chimie organique ?','Des réactions où un nucléophile (riche','Des réactions où un nucléophile (riche en e⁻) remplace un groupe partant (X) sur un carbone ; SN2 : bimolécule, inversion de configuration ; SN1 : unimolécule, racémisation'),
('S0096','v2_supp_10_chimie.sql',10,'Qu''est-ce que la polymérisation et ses types principaux ?','La réaction assemblant de nombreuses','La réaction assemblant de nombreuses petites molécules (monomères) en une longue chaîne (polymère) ; types : addition (polyéthylène) et condensation (Nylon, polyester) avec ou sans élimination d''eau'),
('S0097','v2_supp_10_chimie.sql',10,'Qu''est-ce que la nomenclature IUPAC des composés organiques et ses règles de base ?','Un système international basant le nom','Un système international basant le nom sur la chaîne carbonée la plus longue (méthane/éthane/propane... = 1/2/3... carbones), les ramifications et les groupes fonctionnels'),
('S0098','v2_supp_10_chimie.sql',10,'Qu''est-ce que les hydrocarbures aromatiques (benzène et dérivés) et leurs propriétés ?','Des composés cycliques insaturés','Des composés cycliques insaturés stabilisés par délocalisation d''électrons (aromaticité) ; le benzène (C₆H₆) et ses dérivés (toluène, naphtalène) sont peu réactifs aux additions mais réactifs en substitution'),
('S0099','v2_supp_10_chimie.sql',10,'Qu''est-ce que les lipides en chimie organique et leur structure ?','Des biomolécules hydrophobes incluant','Des biomolécules hydrophobes incluant triglycérides (esters glycérol+acides gras), phospholipides (membranes), stérols (cholestérol, hormones stéroïdes)'),
('S0100','v2_supp_10_chimie.sql',10,'Qu''est-ce que les glucides (saccharides) et leur structure en chimie organique ?','Des biomolécules de formule générale','Des biomolécules de formule générale (CH₂O)n comprenant monosaccharides (glucose, fructose), disaccharides (saccharose, lactose) et polysaccharides (amidon, cellulose, glycogène)'),
('S0101','v2_supp_10_chimie.sql',10,'Qu''est-ce que la chimie verte (chimie durable) et ses 12 principes ?','La philosophie de conception chimique','La philosophie de conception chimique minimisant l''utilisation et la génération de substances dangereuses, réduisant les déchets, utilisant des réactifs renouvelables et des processus économes en énergie'),
('S0102','v2_supp_10_chimie.sql',10,'Qu''est-ce qu''une pile électrochimique et comment produit-elle de l''électricité ?','Un dispositif transformant l''énergie','Un dispositif transformant l''énergie chimique en énergie électrique via une réaction redox spontanée ; à l''anode (oxydation) les e⁻ circulent vers la cathode (réduction) via un circuit externe'),
('S0103','v2_supp_10_chimie.sql',10,'Qu''est-ce que l''électrolyse et comment diffère-t-elle d''une pile galvanique ?','L''électrolyse utilise de l''électricité','L''électrolyse utilise de l''électricité pour forcer une réaction chimique non spontanée (inverse d''une pile) ; applications : raffinage des métaux, galvanoplastie, production de chlore et aluminium'),
('S0104','v2_supp_10_chimie.sql',10,'Qu''est-ce que la corrosion et comment la prévenir ?','La dégradation électrochimique d''un','La dégradation électrochimique d''un métal en milieu humide/acide (réaction redox spontanée) ; prévention : revêtements protecteurs, protection cathodique, alliages résistants (acier inoxydable)'),
('S0105','v2_supp_10_chimie.sql',10,'Qu''est-ce que la force électromotrice (FEM) d''une pile et comment la calculer ?','E = E°_cathode - E°_anode','E = E°_cathode - E°_anode (potentiels standards de réduction) ; si E > 0, la réaction est spontanée ; la FEM diminue avec l''utilisation selon la loi de Nernst'),
('S0106','v2_supp_10_chimie.sql',10,'Qu''est-ce qu''une batterie lithium-ion et pourquoi domine-t-elle dans les appareils portables ?','Une batterie rechargeable où les ions','Une batterie rechargeable où les ions Li⁺ migrent entre électrodes de graphite et d''oxyde de cobalt-lithium, offrant haute densité d''énergie, légèreté et longue durée de vie, contrairement aux batteries Ni-Cd'),
('S0107','v2_supp_10_chimie.sql',10,'Qu''est-ce que les lois de Faraday en électrolyse ?','1ère','1ère : la masse déposée est proportionnelle à la charge électrique : m = (M × I × t) / (n × F) ; 2ème : à même charge, les masses déposées sont proportionnelles aux masses molaires divisées par la charge'),
('S0108','v2_supp_10_chimie.sql',10,'Qu''est-ce que les piles à combustible et leur potentiel pour l''énergie propre ?','Des dispositifs électrochimiques','Des dispositifs électrochimiques convertissant directement un combustible (hydrogène, méthane) en électricité via une réaction redox, avec eau et chaleur comme seuls sous-produits pour H₂/O₂'),
('S0109','v2_supp_10_chimie.sql',10,'Qu''est-ce que la photochimie et l''effet photovoltaïque en chimie ?','L''étude des réactions déclenchées par','L''étude des réactions déclenchées par la lumière ; l''effet photovoltaïque dans les cellules solaires au silicium (semi-conducteur) convertit les photons en électrons via la création de paires électron-trou dans une jonction p-n'),
('S0110','v2_supp_10_chimie.sql',10,'Comment la chimie contribue-t-elle à la sécurité alimentaire et à l''agriculture en Haïti ?','La chimie fournit les engrais minéraux','La chimie fournit les engrais minéraux (NPK), les pesticides, les herbicides, et les biotechnologies agricoles ; en Haïti, l''accès limité aux intrants chimiques de qualité et les alternatives organiques (compostage, biofertilisants) sont des enjeux majeurs'),
('S0111','v2_supp_10_chimie.sql',10,'Qu''est-ce que la spectroscopie et son utilisation en chimie analytique ?','L''ensemble des techniques d''analyse','L''ensemble des techniques d''analyse basées sur l''interaction de la matière avec les ondes électromagnétiques (IR, UV-Vis, RMN, masse) permettant d''identifier et de quantifier les composés chimiques'),
('S0112','v2_supp_11_biologie_ns1ns2.sql',11,'Quelle est la théorie cellulaire fondamentale formulée au XIXe siècle ?','Toute cellule provient d''une cellule','Toute cellule provient d''une cellule préexistante, et la cellule est l''unité de base du vivant'),
('S0113','v2_supp_11_biologie_ns1ns2.sql',11,'Quelle est la principale différence entre cellule procaryote et eucaryote ?','La présence ou l''absence d''un noyau','La présence ou l''absence d''un noyau membranaire'),
('S0114','v2_supp_11_biologie_ns1ns2.sql',11,'Quel organite est responsable de la synthèse des protéines ?','Le ribosome','Le ribosome'),
('S0115','v2_supp_11_biologie_ns1ns2.sql',11,'Quelle est la fonction principale de la mitochondrie ?','Production d''ATP par respiration','Production d''ATP par respiration cellulaire aérobie'),
('S0116','v2_supp_11_biologie_ns1ns2.sql',11,'Quelle est la composition de la membrane plasmique selon le modèle de la mosaïque fluide ?','Une bicouche phospholipidique avec des','Une bicouche phospholipidique avec des protéines insérées'),
('S0117','v2_supp_11_biologie_ns1ns2.sql',11,'Quel organite est exclusif aux cellules végétales et permet la photosynthèse ?','Le chloroplaste','Le chloroplaste'),
('S0118','v2_supp_11_biologie_ns1ns2.sql',11,'Qu''est-ce que le réticulum endoplasmique rugueux (RER) ?','Un réseau de membranes parsemé de','Un réseau de membranes parsemé de ribosomes, synthétisant et triant les protéines sécrétées'),
('S0119','v2_supp_11_biologie_ns1ns2.sql',11,'Quelle est la fonction de l''appareil de Golgi ?','Tri','Tri, modification et emballage des protéines en vésicules pour l''exportation'),
('S0120','v2_supp_11_biologie_ns1ns2.sql',11,'Qu''est-ce que la paroi cellulaire végétale et quel est son composant principal ?','Une enveloppe rigide externe composée','Une enveloppe rigide externe composée principalement de cellulose'),
('S0121','v2_supp_11_biologie_ns1ns2.sql',11,'Quel est le rôle du lysosome dans la cellule animale ?','Digestion des macromolécules et des','Digestion des macromolécules et des organites endommagés par des enzymes hydrolytiques'),
('S0122','v2_supp_11_biologie_ns1ns2.sql',11,'Comment se réalise la diffusion simple à travers la membrane plasmique ?','Du milieu le plus concentré vers le','Du milieu le plus concentré vers le moins concentré, sans énergie'),
('S0123','v2_supp_11_biologie_ns1ns2.sql',11,'Qu''est-ce que l''osmose et son importance pour les cellules vivantes ?','Le mouvement de l''eau à travers une','Le mouvement de l''eau à travers une membrane semi-perméable du milieu hypotonique vers le milieu hypertonique'),
('S0124','v2_supp_11_biologie_ns1ns2.sql',11,'Quel microscope utilise-t-on pour observer la structure interne fine d''une cellule (ultrastructure) ?','Le microscope électronique à','Le microscope électronique à transmission (MET)'),
('S0125','v2_supp_11_biologie_ns1ns2.sql',11,'Qu''est-ce que la spécialisation cellulaire (différenciation) dans les organismes pluricellulaires ?','Le processus par lequel des cellules','Le processus par lequel des cellules identiques au départ acquièrent des structures et fonctions différentes selon l''expression différentielle des gènes'),
('S0126','v2_supp_11_biologie_ns1ns2.sql',11,'Quel est le rôle du centrosome dans la division cellulaire ?','Organisation du fuseau mitotique','Organisation du fuseau mitotique permettant la ségrégation des chromosomes'),
('S0127','v2_supp_11_biologie_ns1ns2.sql',11,'Quelle est la différence fondamentale entre mitose et méiose en termes de résultats ?','La mitose produit 2 cellules diploïdes','La mitose produit 2 cellules diploïdes identiques ; la méiose produit 4 cellules haploïdes génétiquement différentes'),
('S0128','v2_supp_11_biologie_ns1ns2.sql',11,'Dans quel ordre se succèdent les phases de la mitose ?','Prophase, métaphase, anaphase, télophase','Prophase, métaphase, anaphase, télophase'),
('S0129','v2_supp_11_biologie_ns1ns2.sql',11,'Qu''est-ce que la cytocinèse et quand se produit-elle ?','La division du cytoplasme se produisant','La division du cytoplasme se produisant après la télophase pour former deux cellules filles'),
('S0130','v2_supp_11_biologie_ns1ns2.sql',11,'Qu''est-ce que le crossing-over (enjambement) en méiose et son importance ?','L''échange de segments homologues entre','L''échange de segments homologues entre chromosomes pendant la méiose I, créant de nouvelles combinaisons génétiques'),
('S0131','v2_supp_11_biologie_ns1ns2.sql',11,'Qu''est-ce que le cycle cellulaire et quelles en sont les phases principales ?','L''ensemble des étapes de la vie d''une','L''ensemble des étapes de la vie d''une cellule : interphase (G1, S, G2) + phase mitotique'),
('S0132','v2_supp_11_biologie_ns1ns2.sql',11,'Qu''est-ce qu''un chromosome homologue et comment diffère-t-il d''une chromatide sœur ?','Les chromosomes homologues sont des','Les chromosomes homologues sont des paires de même taille et séquence, une d''origine maternelle/paternelle ; les chromatides sœurs sont les deux copies d''un chromosome répliqué'),
('S0133','v2_supp_11_biologie_ns1ns2.sql',11,'Quel est le rôle des points de contrôle (checkpoints) du cycle cellulaire ?','Vérifier que chaque phase est','Vérifier que chaque phase est correctement complétée avant de passer à la suivante, évitant les erreurs génétiques'),
('S0134','v2_supp_11_biologie_ns1ns2.sql',11,'Qu''est-ce que l''apoptose et quel est son rôle dans l''organisme ?','La mort cellulaire programmée','La mort cellulaire programmée permettant d''éliminer les cellules endommagées ou en surnombre'),
('S0135','v2_supp_11_biologie_ns1ns2.sql',11,'En méiose, à quelle phase les chromosomes homologues se séparent-ils ?','Anaphase I','Anaphase I'),
('S0136','v2_supp_11_biologie_ns1ns2.sql',11,'Qu''est-ce que la polyploïdie et dans quel règne est-elle fréquente ?','La présence de plus de deux sets de','La présence de plus de deux sets de chromosomes, fréquente chez les végétaux'),
('S0137','v2_supp_11_biologie_ns1ns2.sql',11,'Qu''est-ce que la spermatogenèse et où se déroule-t-elle ?','La formation des spermatozoïdes par','La formation des spermatozoïdes par méiose dans les testicules'),
('S0138','v2_supp_11_biologie_ns1ns2.sql',11,'Quel est l''effet d''une non-disjonction chromosomique en méiose ?','Des gamètes avec un chromosome en plus','Des gamètes avec un chromosome en plus ou en moins, pouvant causer des trisomies comme la trisomie 21'),
('S0139','v2_supp_11_biologie_ns1ns2.sql',11,'Pourquoi la méiose est-elle essentielle à la reproduction sexuée des organismes diploïdes ?','Elle réduit la ploïdie de moitié','Elle réduit la ploïdie de moitié, garantissant que la fécondation rétablit le nombre chromosomique diploïde normal'),
('S0140','v2_supp_11_biologie_ns1ns2.sql',11,'Quelle est la première loi de Mendel (loi de ségrégation) ?','Les deux allèles d''un gène se séparent','Les deux allèles d''un gène se séparent pendant la méiose, chaque gamète n''en portant qu''un seul'),
('S0141','v2_supp_11_biologie_ns1ns2.sql',11,'Qu''est-ce que la deuxième loi de Mendel (loi d''assortiment indépendant) ?','Les allèles de deux gènes situés sur','Les allèles de deux gènes situés sur des chromosomes différents se distribuent indépendamment lors de la méiose'),
('S0142','v2_supp_11_biologie_ns1ns2.sql',11,'Dans un croisement Aa × Aa, quelle est la proportion phénotypique attendue si A est dominant ?','3/4 dominant : 1/4 récessif','3/4 dominant : 1/4 récessif'),
('S0143','v2_supp_11_biologie_ns1ns2.sql',11,'Qu''est-ce qu''un allèle récessif et comment s''exprime-t-il ?','Un allèle qui ne s''exprime','Un allèle qui ne s''exprime phénotypiquement qu''à l''état homozygote (aa), masqué par l''allèle dominant à l''état hétérozygote'),
('S0144','v2_supp_11_biologie_ns1ns2.sql',11,'Qu''est-ce que la codominance et quel en est un exemple classique ?','L''expression simultanée et complète des','L''expression simultanée et complète des deux allèles chez l''hétérozygote, comme les groupes sanguins AB'),
('S0145','v2_supp_11_biologie_ns1ns2.sql',11,'Qu''est-ce que la liaison génique (linkage) et son effet sur la 2ème loi de Mendel ?','Des gènes sur le même chromosome qui','Des gènes sur le même chromosome qui tendent à être transmis ensemble, violant la 2ème loi de Mendel'),
('S0146','v2_supp_11_biologie_ns1ns2.sql',11,'Comment les groupes sanguins ABO sont-ils déterminés génétiquement ?','Par un gène à 3 allèles (IA','Par un gène à 3 allèles (IA, IB, i) dont IA et IB sont codominants et i est récessif'),
('S0147','v2_supp_11_biologie_ns1ns2.sql',11,'Qu''est-ce que l''hérédité liée au sexe (hérédité gonosomique) ?','La transmission de gènes portés sur les','La transmission de gènes portés sur les chromosomes sexuels (X ou Y), avec des ratios différents selon le sexe'),
('S0148','v2_supp_11_biologie_ns1ns2.sql',11,'Quel est le résultat d''un croisement test (testcross) entre un individu de génotype inconnu et un individu homozygote récessif ?','Les proportions phénotypiques révèlent','Les proportions phénotypiques révèlent directement le génotype de l''individu inconnu'),
('S0149','v2_supp_11_biologie_ns1ns2.sql',11,'Qu''est-ce que la pléiotropie en génétique ?','Un gène influençant plusieurs','Un gène influençant plusieurs caractères phénotypiques différents'),
('S0150','v2_supp_11_biologie_ns1ns2.sql',11,'Comment calcule-t-on la fréquence de recombinaison entre deux gènes liés ?','En divisant le nombre de descendants','En divisant le nombre de descendants recombinants par le total de descendants × 100 (en centiMorgans)'),
('S0151','v2_supp_11_biologie_ns1ns2.sql',11,'Qu''est-ce que l''épistasie en génétique ?','L''interaction entre deux gènes','L''interaction entre deux gènes différents où l''un masque l''expression de l''autre'),
('S0152','v2_supp_11_biologie_ns1ns2.sql',11,'Quelle est la structure de base d''un acide aminé ?','Un carbone central (Cα) portant un','Un carbone central (Cα) portant un groupement amine (-NH2), un carboxyle (-COOH), un hydrogène et une chaîne latérale (R)'),
('S0153','v2_supp_11_biologie_ns1ns2.sql',11,'Qu''est-ce qu''une liaison peptidique et comment se forme-t-elle ?','Une liaison covalente entre le','Une liaison covalente entre le groupement carboxyle d''un acide aminé et le groupement amine du suivant, libérant de l''eau (condensation)'),
('S0154','v2_supp_11_biologie_ns1ns2.sql',11,'Qu''est-ce que la structure secondaire d''une protéine ?','La conformation locale stabilisée par','La conformation locale stabilisée par des liaisons hydrogène : hélice α et feuillet β'),
('S0155','v2_supp_11_biologie_ns1ns2.sql',11,'Qu''est-ce que la dénaturation d''une protéine ?','La perte de la structure','La perte de la structure tridimensionnelle (et donc de la fonction) par rupture des liaisons non covalentes sous l''effet de la chaleur, du pH, etc.'),
('S0156','v2_supp_11_biologie_ns1ns2.sql',11,'Quelle est la différence entre un acide gras saturé et insaturé ?','Les acides gras saturés n''ont pas de','Les acides gras saturés n''ont pas de double liaison C-C ; les insaturés en ont au moins une, les rendant plus fluides à basse température'),
('S0157','v2_supp_11_biologie_ns1ns2.sql',11,'Qu''est-ce que l''ATP et pourquoi est-il la "monnaie énergétique" de la cellule ?','L''adénosine triphosphate','L''adénosine triphosphate, molécule dont l''hydrolyse libère de l''énergie libre utilisable par toutes les réactions cellulaires'),
('S0158','v2_supp_11_biologie_ns1ns2.sql',11,'Quelle est la différence entre un monosaccharide, un disaccharide et un polysaccharide ?','Les monosaccharides sont des sucres','Les monosaccharides sont des sucres simples (glucose, fructose) ; les disaccharides sont deux sucres liés (saccharose) ; les polysaccharides sont des longues chaînes (amidon, cellulose)'),
('S0159','v2_supp_11_biologie_ns1ns2.sql',11,'Qu''est-ce qu''un nucléotide et quelle est sa structure ?','Une molécule composée d''un sucre','Une molécule composée d''un sucre pentose (ribose ou désoxyribose), d''un groupement phosphate et d''une base azotée'),
('S0160','v2_supp_11_biologie_ns1ns2.sql',11,'Quelle est la différence entre l''ADN et l''ARN en termes de structure ?','L''ADN est double brin avec désoxyribose','L''ADN est double brin avec désoxyribose et thymine ; l''ARN est simple brin avec ribose et uracile'),
('S0161','v2_supp_11_biologie_ns1ns2.sql',11,'Qu''est-ce qu''une enzyme et comment catalyse-t-elle une réaction ?','Un biocatalyseur protéique abaissant','Un biocatalyseur protéique abaissant l''énergie d''activation d''une réaction sans être consommé, grâce à son site actif spécifique'),
('S0162','v2_supp_11_biologie_ns1ns2.sql',11,'Qu''est-ce que la spécificité enzymatique et comment s''explique-t-elle ?','Chaque enzyme ne catalyse qu''un type de','Chaque enzyme ne catalyse qu''un type de réaction/substrat grâce à la complémentarité de forme et chimique entre site actif et substrat (modèle clé-serrure ou «induced fit»)'),
('S0163','v2_supp_11_biologie_ns1ns2.sql',11,'Comment le pH et la température affectent-ils l''activité enzymatique ?','Chaque enzyme a un pH et une','Chaque enzyme a un pH et une température optimaux ; au-delà des valeurs optimales, l''activité diminue et la dénaturation peut survenir'),
('S0164','v2_supp_11_biologie_ns1ns2.sql',11,'Quelle est l''équation globale de la photosynthèse ?','6CO2 + 6H2O + lumière → C6H12O6 + 6O2','6CO2 + 6H2O + lumière → C6H12O6 + 6O2'),
('S0165','v2_supp_11_biologie_ns1ns2.sql',11,'Où se déroulent les réactions lumineuses (phase claire) de la photosynthèse ?','Dans les membranes des thylakoïdes du','Dans les membranes des thylakoïdes du chloroplaste'),
('S0166','v2_supp_11_biologie_ns1ns2.sql',11,'Qu''est-ce que le cycle de Calvin (phase sombre) de la photosynthèse ?','La fixation du CO2 en glucides en','La fixation du CO2 en glucides en utilisant l''ATP et le NADPH produits par les réactions lumineuses, dans le stroma'),
('S0167','v2_supp_11_biologie_ns1ns2.sql',11,'Quelle est l''équation globale de la respiration cellulaire aérobie ?','C6H12O6 + 6O2 → 6CO2 + 6H2O + ATP','C6H12O6 + 6O2 → 6CO2 + 6H2O + ATP'),
('S0168','v2_supp_11_biologie_ns1ns2.sql',11,'Quelles sont les trois étapes principales de la respiration cellulaire aérobie ?','Glycolyse (cytoplasme)','Glycolyse (cytoplasme), cycle de Krebs (matrice mitochondriale), chaîne respiratoire (membrane interne mitochondriale)'),
('S0169','v2_supp_11_biologie_ns1ns2.sql',11,'Qu''est-ce que la fermentation et dans quelles conditions se produit-elle ?','La production d''ATP en absence d''O2','La production d''ATP en absence d''O2 (anaérobie), régénérant le NAD+ pour permettre la glycolyse de continuer'),
('S0170','v2_supp_11_biologie_ns1ns2.sql',11,'Qu''est-ce que le coefficient respiratoire (CR) et que révèle-t-il ?','Le rapport CO2 produit / O2 consommé','Le rapport CO2 produit / O2 consommé, indicateur du substrat oxydé (CR=1 glucides, ~0,7 lipides, ~0,8 protéines)'),
('S0171','v2_supp_11_biologie_ns1ns2.sql',11,'Quel est le rôle de l''ATP synthase dans la mitochondrie ?','Synthétiser l''ATP en utilisant le','Synthétiser l''ATP en utilisant le gradient de protons (H+) établi par la chaîne respiratoire (chimiosmose)'),
('S0172','v2_supp_11_biologie_ns1ns2.sql',11,'Quelle est la différence entre l''autotrophie et l''hétérotrophie ?','Les autotrophes synthétisent leur','Les autotrophes synthétisent leur propre matière organique à partir de CO2 (photosynthèse) ; les hétérotrophes doivent consommer de la matière organique préformée'),
('S0173','v2_supp_11_biologie_ns1ns2.sql',11,'Comment la concentration en CO2 affecte-t-elle le taux de photosynthèse ?','Jusqu''à une concentration optimale','Jusqu''à une concentration optimale, une augmentation de CO2 augmente le taux de photosynthèse (facteur limitant)'),
('S0174','v2_supp_11_biologie_ns1ns2.sql',11,'Qu''est-ce que le point de compensation photosynthétique ?','L''intensité lumineuse à laquelle la','L''intensité lumineuse à laquelle la photosynthèse brute égale la respiration, le bilan net de CO2 étant nul'),
('S0175','v2_supp_11_biologie_ns3ns4.sql',11,'Qui a déterminé la structure en double hélice de l''ADN et en quelle année ?','Watson et Crick en 1953','Watson et Crick en 1953, s''appuyant sur les données de Franklin'),
('S0176','v2_supp_11_biologie_ns3ns4.sql',11,'Qu''est-ce que la complémentarité des bases azotées dans l''ADN ?','Adénine (A) s''apparie avec Thymine (T)','Adénine (A) s''apparie avec Thymine (T) par 2 liaisons H ; Guanine (G) avec Cytosine (C) par 3 liaisons H'),
('S0177','v2_supp_11_biologie_ns3ns4.sql',11,'Qu''est-ce que la réplication semi-conservative de l''ADN ?','Chaque brin parental sert de matrice','Chaque brin parental sert de matrice pour un nouveau brin complémentaire, donnant 2 molécules filles hybrides (1 brin parental + 1 nouveau)'),
('S0178','v2_supp_11_biologie_ns3ns4.sql',11,'Quel est le rôle de l''ADN polymérase dans la réplication ?','Synthétiser le nouveau brin d''ADN en','Synthétiser le nouveau brin d''ADN en lisant le brin matrice dans le sens 3''→5'' et en ajoutant des nucléotides en 5''→3'''),
('S0179','v2_supp_11_biologie_ns3ns4.sql',11,'Qu''est-ce que la transcription et où se déroule-t-elle dans une cellule eucaryote ?','La synthèse d''un ARNm à partir d''un','La synthèse d''un ARNm à partir d''un brin d''ADN matrice par l''ARN polymérase, dans le noyau'),
('S0180','v2_supp_11_biologie_ns3ns4.sql',11,'Qu''est-ce que la traduction et où se déroule-t-elle ?','La synthèse d''une chaîne polypeptidique','La synthèse d''une chaîne polypeptidique à partir du code de l''ARNm, au niveau des ribosomes dans le cytoplasme'),
('S0181','v2_supp_11_biologie_ns3ns4.sql',11,'Qu''est-ce qu''un codon et comment code-t-il pour un acide aminé ?','Une séquence de 3 nucléotides de l''ARNm','Une séquence de 3 nucléotides de l''ARNm qui spécifie un acide aminé particulier ou un signal stop'),
('S0182','v2_supp_11_biologie_ns3ns4.sql',11,'Qu''est-ce que le traitement (maturation) de l''ARNm chez les eucaryotes ?','La coiffe 5''','La coiffe 5'', la queue poly-A 3'' et l''épissage des introns (retrait) pour ne garder que les exons'),
('S0183','v2_supp_11_biologie_ns3ns4.sql',11,'Qu''est-ce que l''épissage alternatif et quelle est son importance ?','La possibilité d''inclure ou d''exclure','La possibilité d''inclure ou d''exclure différents exons lors de l''épissage, produisant plusieurs protéines à partir d''un seul gène'),
('S0184','v2_supp_11_biologie_ns3ns4.sql',11,'Qu''est-ce qu''une mutation ponctuelle et quels en sont les types ?','Un changement d''un seul nucléotide dans','Un changement d''un seul nucléotide dans la séquence d''ADN : substitution (transition/transversion), insertion ou délétion'),
('S0185','v2_supp_11_biologie_ns3ns4.sql',11,'Quel est le rôle de l''ARN de transfert (ARNt) dans la traduction ?','Il transporte un acide aminé spécifique','Il transporte un acide aminé spécifique vers le ribosome et reconnaît le codon de l''ARNm via son anticodon complémentaire'),
('S0186','v2_supp_11_biologie_ns3ns4.sql',11,'Qu''est-ce que l''opéron lac chez E. coli et son intérêt pour comprendre la régulation des gènes ?','Un ensemble de gènes structuraux sous','Un ensemble de gènes structuraux sous contrôle d''un promoteur commun, régulés par un répresseur et un inducteur (lactose), modèle de la régulation génique procaryote'),
('S0187','v2_supp_11_biologie_ns3ns4.sql',11,'Quel est le rôle de la télomérase dans les cellules eucaryotes ?','Allonger les télomères qui','Allonger les télomères qui raccourcissent à chaque réplication, maintenant l''intégrité chromosomique dans les cellules germinales et les cellules souches'),
('S0188','v2_supp_11_biologie_ns3ns4.sql',11,'Quelle est la théorie de l''évolution par la sélection naturelle proposée par Darwin ?','Les individus les mieux adaptés à leur','Les individus les mieux adaptés à leur environnement survivent préférentiellement et se reproduisent davantage, transmettant leurs caractères avantageux'),
('S0189','v2_supp_11_biologie_ns3ns4.sql',11,'Quelle est la différence entre l''évolution de Lamarck et celle de Darwin ?','Lamarck proposait l''hérédité des','Lamarck proposait l''hérédité des caractères acquis et une volonté interne ; Darwin proposait la variation héréditaire aléatoire et la sélection naturelle'),
('S0190','v2_supp_11_biologie_ns3ns4.sql',11,'Qu''est-ce que la dérive génétique et comment diffère-t-elle de la sélection naturelle ?','La dérive génétique est une variation','La dérive génétique est une variation aléatoire des fréquences alléliques (non due à l''adaptation) ; elle est plus forte dans les petites populations'),
('S0191','v2_supp_11_biologie_ns3ns4.sql',11,'Qu''est-ce que la spéciation allopatrique et quand se produit-elle ?','La formation d''une nouvelle espèce','La formation d''une nouvelle espèce suite à l''isolement géographique de populations d''une même espèce (flux génique interrompu, divergence)'),
('S0192','v2_supp_11_biologie_ns3ns4.sql',11,'Quelles sont les preuves moléculaires de l''évolution commune ?','La comparaison des séquences','La comparaison des séquences d''ADN/protéines montrant que des espèces apparentées partagent davantage de séquences communes'),
('S0193','v2_supp_11_biologie_ns3ns4.sql',11,'Qu''est-ce que la classification phylogénétique (cladistique) ?','Regrouper les organismes selon leur','Regrouper les organismes selon leur histoire évolutive commune (ancêtre partagé), basée sur les synapomorphies (caractères dérivés partagés)'),
('S0194','v2_supp_11_biologie_ns3ns4.sql',11,'Quel est le principe de la théorie synthétique de l''évolution (néo-darwinisme) ?','La synthèse de la sélection naturelle','La synthèse de la sélection naturelle (Darwin) et de la génétique mendélienne et des populations, intégrant mutations, dérive, flux génique et sélection comme forces évolutives'),
('S0195','v2_supp_11_biologie_ns3ns4.sql',11,'Qu''est-ce qu''un organe homologue et comment diffère-t-il d''un organe analogue ?','Les organes homologues ont une même','Les organes homologues ont une même origine embryonnaire mais des fonctions différentes (bras humain/aile de chauve-souris) ; les analogues ont des fonctions similaires mais des origines différentes (aile d''oiseau/insecte)'),
('S0196','v2_supp_11_biologie_ns3ns4.sql',11,'Quelle est la signification de la nomenclature binominale de Linné ?','Chaque espèce est nommée par deux mots','Chaque espèce est nommée par deux mots latins : le genre (majuscule) et l''épithète spécifique (minuscule), ex. Homo sapiens'),
('S0197','v2_supp_11_biologie_ns3ns4.sql',11,'Qu''est-ce que la coévolution et quel en est un exemple classique ?','L''évolution mutuelle de deux espèces','L''évolution mutuelle de deux espèces interagissant, chaque changement de l''une exerçant une pression sélective sur l''autre (ex. fleur et pollinisateur)'),
('S0198','v2_supp_11_biologie_ns3ns4.sql',11,'Qu''est-ce que l''endosymbiose et comment explique-t-elle l''origine des mitochondries et des chloroplastes ?','La théorie selon laquelle des bactéries','La théorie selon laquelle des bactéries ont été englouties par des cellules hôtes sans être digérées, devenant des organites (Lynn Margulis)'),
('S0199','v2_supp_11_biologie_ns3ns4.sql',11,'Qu''est-ce que la sélection sexuelle et comment diffère-t-elle de la sélection naturelle de survie ?','La sélection sexuelle favorise les','La sélection sexuelle favorise les traits améliorant le succès reproducteur (séduction des partenaires ou compétition entre mâles) même s''ils réduisent la survie'),
('S0200','v2_supp_11_biologie_ns3ns4.sql',11,'Qu''est-ce qu''un écosystème et quels en sont les composants principaux ?','L''ensemble formé par une communauté','L''ensemble formé par une communauté d''organismes vivants (biocénose) et leur milieu physique (biotope), interconnectés par des flux d''énergie et de matière'),
('S0201','v2_supp_11_biologie_ns3ns4.sql',11,'Qu''est-ce que la chaîne alimentaire et le réseau trophique ?','La chaîne alimentaire montre les','La chaîne alimentaire montre les relations proie-prédateur en séquence linéaire ; le réseau trophique représente toutes les interactions alimentaires complexes d''un écosystème'),
('S0202','v2_supp_11_biologie_ns3ns4.sql',11,'Qu''est-ce que le flux d''énergie dans un écosystème et la règle des 10% ?','L''énergie circule à sens unique','L''énergie circule à sens unique (non cyclique) ; environ 10% de l''énergie d''un niveau trophique est transférée au niveau suivant'),
('S0203','v2_supp_11_biologie_ns3ns4.sql',11,'Qu''est-ce que le cycle du carbone et son importance pour le climat ?','Le mouvement du carbone entre','Le mouvement du carbone entre atmosphère (CO2), organismes (photosynthèse/respiration), océans et sédiments (fossiles) ; sa perturbation par les combustibles fossiles cause le changement climatique'),
('S0204','v2_supp_11_biologie_ns3ns4.sql',11,'Qu''est-ce que la succession écologique et quels en sont les types ?','Le remplacement progressif de','Le remplacement progressif de communautés dans un habitat au fil du temps : primaire (substrat nu) ou secondaire (après perturbation d''un écosystème existant)'),
('S0205','v2_supp_11_biologie_ns3ns4.sql',11,'Qu''est-ce que la biodiversité et comment la mesure-t-on ?','La variété du vivant à l''échelle des','La variété du vivant à l''échelle des gènes (diversité génétique), des espèces (richesse spécifique) et des écosystèmes ; mesurée par des indices comme Shannon ou Simpson'),
('S0206','v2_supp_11_biologie_ns3ns4.sql',11,'Quelles sont les principales causes actuelles de l''érosion de la biodiversité ?','La destruction et fragmentation des','La destruction et fragmentation des habitats, la surexploitation, les espèces invasives, la pollution et le changement climatique (acronyme HIPPO)'),
('S0207','v2_supp_11_biologie_ns3ns4.sql',11,'Qu''est-ce que la niche écologique d''une espèce ?','L''ensemble des rôles fonctionnels et','L''ensemble des rôles fonctionnels et des ressources utilisées par une espèce dans son écosystème (ce qu''elle mange, comment elle est mangée, ses interactions biogéochimiques)'),
('S0208','v2_supp_11_biologie_ns3ns4.sql',11,'Qu''est-ce que le principe d''exclusion compétitive de Gause ?','Deux espèces occupant exactement la','Deux espèces occupant exactement la même niche écologique ne peuvent coexister indéfiniment ; l''une exclut l''autre'),
('S0209','v2_supp_11_biologie_ns3ns4.sql',11,'Qu''est-ce que le changement climatique et ses effets sur les écosystèmes haïtiens ?','Le réchauffement global causé','Le réchauffement global causé principalement par les émissions de GES humaines, aggravant la déforestation haïtienne, les cyclones, les sécheresses et la perte de biodiversité marine'),
('S0210','v2_supp_11_biologie_ns3ns4.sql',11,'Qu''est-ce que la biorestauration et comment peut-elle aider des écosystèmes dégradés ?','L''utilisation d''organismes vivants','L''utilisation d''organismes vivants (plantes, bactéries, champignons) pour dégrader des polluants ou restaurer des écosystèmes endommagés'),
('S0211','v2_supp_11_biologie_ns3ns4.sql',11,'Qu''est-ce que la biologie de la conservation et ses outils principaux ?','La discipline scientifique visant à','La discipline scientifique visant à préserver la biodiversité en combinant écologie, génétique des populations, sociologie et politique pour informer les décisions de conservation'),
('S0212','v2_supp_11_biologie_ns3ns4.sql',11,'Qu''est-ce que la PCR (réaction en chaîne par polymérase) et à quoi sert-elle ?','Une technique d''amplification in vitro','Une technique d''amplification in vitro d''une séquence d''ADN spécifique permettant d''en obtenir des millions de copies en quelques heures'),
('S0213','v2_supp_11_biologie_ns3ns4.sql',11,'Qu''est-ce que la technologie CRISPR-Cas9 et ses applications ?','Un système d''édition génomique précis','Un système d''édition génomique précis permettant de couper l''ADN à un endroit spécifique et d''y ajouter, supprimer ou modifier des séquences'),
('S0214','v2_supp_11_biologie_ns3ns4.sql',11,'Qu''est-ce que le clonage moléculaire et ses étapes principales ?','L''insertion d''un fragment d''ADN dans un','L''insertion d''un fragment d''ADN dans un vecteur (plasmide), transformation d''une bactérie hôte, et production de nombreuses copies du gène d''intérêt'),
('S0215','v2_supp_11_biologie_ns3ns4.sql',11,'Qu''est-ce que les organismes génétiquement modifiés (OGM) et leurs controverses ?','Des organismes dont le génome a été','Des organismes dont le génome a été modifié par biotechnologie pour exprimer de nouveaux caractères, au cœur de débats sur la biosécurité, l''éthique et la brevetabilité du vivant'),
('S0216','v2_supp_11_biologie_ns3ns4.sql',11,'Qu''est-ce que la thérapie génique et quels sont ses principes ?','L''introduction d''une version','L''introduction d''une version fonctionnelle d''un gène défectueux dans les cellules d''un patient pour traiter une maladie génétique'),
('S0217','v2_supp_11_biologie_ns3ns4.sql',11,'Qu''est-ce que la médecine personnalisée et comment la génomique y contribue-t-elle ?','L''adaptation des traitements médicaux','L''adaptation des traitements médicaux aux caractéristiques génétiques individuelles du patient, permettant des thérapies plus efficaces avec moins d''effets secondaires'),
('S0218','v2_supp_11_biologie_ns3ns4.sql',11,'Qu''est-ce que les cellules souches et leurs types principaux ?','Des cellules indifférenciées capables','Des cellules indifférenciées capables de s''auto-renouveler et de se différencier : totipotentes (embryon précoce), pluripotentes (blastocyste), multipotentes (adultes)'),
('S0219','v2_supp_11_biologie_ns3ns4.sql',11,'Qu''est-ce que la bioinformatique et quel est son rôle en biologie moderne ?','L''utilisation de l''informatique et des','L''utilisation de l''informatique et des mathématiques pour analyser et interpréter les données biologiques (génomes, protéomes), essentielle à l''ère du séquençage haut débit'),
('S0220','v2_supp_11_biologie_ns3ns4.sql',11,'Qu''est-ce que le Projet Génome Humain et ses résultats principaux ?','Le projet international (1990-2003) qui','Le projet international (1990-2003) qui a séquencé les ~3 milliards de paires de bases du génome humain, révélant ~20 000 gènes et ouvrant l''ère de la génomique'),
('S0221','v2_supp_11_biologie_ns3ns4.sql',11,'Quelles sont les applications de la biologie en agroalimentaire et en médecine en Haïti ?','Les biotechnologies peuvent améliorer','Les biotechnologies peuvent améliorer les cultures haïtiennes résistantes à la sécheresse, produire des vaccins locaux, développer des biomédicaments et renforcer la sécurité alimentaire'),
('S0222','v2_supp_12_geologie_ns1ns2.sql',12,'Quelles sont les trois couches principales de la structure interne de la Terre, de l''extérieur vers l''intérieur ?','Croûte, manteau, noyau','Croûte, manteau, noyau'),
('S0223','v2_supp_12_geologie_ns1ns2.sql',12,'Comment les scientifiques étudient-ils l''intérieur de la Terre qu''ils ne peuvent pas observer directement ?','En analysant les ondes sismiques (P et','En analysant les ondes sismiques (P et S) qui se propagent dans la Terre et changent de vitesse selon les milieux traversés'),
('S0224','v2_supp_12_geologie_ns1ns2.sql',12,'Quelle est la différence entre la croûte océanique et la croûte continentale ?','La croûte océanique est plus dense','La croûte océanique est plus dense (basalte, ~3 g/cm³, 5-10 km d''épaisseur) que la croûte continentale (granite, ~2,7 g/cm³, 30-70 km)'),
('S0225','v2_supp_12_geologie_ns1ns2.sql',12,'Qu''est-ce que le manteau terrestre et quel est son état ?','Une couche solide (mais pouvant se','Une couche solide (mais pouvant se déformer sur de longues périodes) composée principalement de péridotite, entre la croûte et le noyau'),
('S0226','v2_supp_12_geologie_ns1ns2.sql',12,'Quelle est la composition probable du noyau terrestre et son état ?','Un noyau externe liquide et un noyau','Un noyau externe liquide et un noyau interne solide, principalement composés de fer et de nickel'),
('S0227','v2_supp_12_geologie_ns1ns2.sql',12,'Qu''est-ce que l''isostasie terrestre ?','L''équilibre gravitationnel entre la','L''équilibre gravitationnel entre la croûte terrestre et le manteau : les parties légères flottent plus haut (montagnes à racines profondes), les parties denses s''enfoncent'),
('S0228','v2_supp_12_geologie_ns1ns2.sql',12,'Qu''est-ce que le gradient géothermique et quelle est sa valeur approximative ?','L''augmentation de température avec la','L''augmentation de température avec la profondeur : environ 30°C/km dans la croûte, avec des variations selon les régions'),
('S0229','v2_supp_12_geologie_ns1ns2.sql',12,'Qu''est-ce que la lithosphère et l''asthénosphère ?','La lithosphère est la partie rigide','La lithosphère est la partie rigide externe (croûte + manteau supérieur) découpée en plaques ; l''asthénosphère est le manteau ductile sur lequel flottent les plaques'),
('S0230','v2_supp_12_geologie_ns1ns2.sql',12,'Qu''est-ce que le champ magnétique terrestre et comment se forme-t-il ?','Il est généré par la rotation du noyau','Il est généré par la rotation du noyau externe liquide (fer-nickel conducteur) créant un effet dynamo ; il nous protège du vent solaire'),
('S0231','v2_supp_12_geologie_ns1ns2.sql',12,'Qu''est-ce que le forage scientifique de Kola (Russie) a révélé sur l''intérieur de la Terre ?','À 12 km de profondeur','À 12 km de profondeur, il a confirmé l''augmentation de température (180°C, plus que prévu) et la présence d''eau à grande profondeur, contredisant certains modèles'),
('S0232','v2_supp_12_geologie_ns1ns2.sql',12,'Comment les météorites nous informent-elles sur la composition du noyau terrestre ?','Les chondrites métalliques (composées','Les chondrites métalliques (composées de fer-nickel) sont considérées comme analogues au matériau du noyau terrestre, car issues d''une même nébuleuse solaire'),
('S0233','v2_supp_12_geologie_ns1ns2.sql',12,'Quel est l''âge estimé de la Terre et comment le détermine-t-on ?','4','4,54 milliards d''années, déterminé par la datation radiométrique (isotopes radioactifs comme l''uranium-plomb) de météorites et des plus anciennes roches terrestres'),
('S0234','v2_supp_12_geologie_ns1ns2.sql',12,'Qui a proposé la théorie de la dérive des continents et sur quelles preuves ?','Alfred Wegener en 1912','Alfred Wegener en 1912, basé sur la complémentarité des côtes, les fossiles communs et les similitudes géologiques entre continents aujourd''hui séparés'),
('S0235','v2_supp_12_geologie_ns1ns2.sql',12,'Qu''est-ce que la dorsale océanique et quel est son rôle dans la tectonique des plaques ?','Une chaîne de montagnes sous-marines où','Une chaîne de montagnes sous-marines où du nouveau fond océanique est créé par remontée de magma (expansion océanique ou «seafloor spreading»)'),
('S0236','v2_supp_12_geologie_ns1ns2.sql',12,'Qu''est-ce que la subduction et dans quel contexte se produit-elle ?','L''enfoncement d''une plaque océanique','L''enfoncement d''une plaque océanique dense sous une autre plaque (océanique ou continentale) dans le manteau, créant des fosses, des volcans et des séismes'),
('S0237','v2_supp_12_geologie_ns1ns2.sql',12,'Quel est le mécanisme moteur du déplacement des plaques tectoniques ?','La convection du manteau','La convection du manteau asthenosphérique : la chaleur interne crée des courants de matière qui entraînent les plaques'),
('S0238','v2_supp_12_geologie_ns1ns2.sql',12,'Comment se forment les chaînes de montagnes selon la tectonique des plaques ?','Par la collision de plaques tectoniques','Par la collision de plaques tectoniques (orogénèse) : la collision Inde-Eurasie a formé l''Himalaya, les Alpes résultent de la collision Afrique-Europe'),
('S0239','v2_supp_12_geologie_ns1ns2.sql',12,'Qu''est-ce qu''une faille transformante et quel en est un exemple célèbre ?','Une faille où deux plaques glissent','Une faille où deux plaques glissent horizontalement l''une par rapport à l''autre, sans création ni destruction de croûte ; ex. la faille de San Andreas en Californie'),
('S0240','v2_supp_12_geologie_ns1ns2.sql',12,'Quelle est la vitesse typique de déplacement des plaques tectoniques ?','Quelques centimètres par an (2-15 cm/an','Quelques centimètres par an (2-15 cm/an selon les plaques), comparable à la croissance des ongles'),
('S0241','v2_supp_12_geologie_ns1ns2.sql',12,'Qu''est-ce que le volcanisme de point chaud et comment diffère-t-il du volcanisme de zone de subduction ?','Les points chauds sont des panaches de','Les points chauds sont des panaches de magma remontant du manteau profond, créant des îles en milieu océanique (Hawaï, Islande) indépendamment des frontières de plaques'),
('S0242','v2_supp_12_geologie_ns1ns2.sql',12,'Comment la tectonique des plaques influence-t-elle la géologie des Caraïbes et d''Haïti ?','La plaque Caraïbe est coincée entre les','La plaque Caraïbe est coincée entre les plaques nord-américaine et sud-américaine ; Haïti est traversée par des failles majeures (Enriquillo, Septentrional) causant une forte sismicité et du volcanisme'),
('S0243','v2_supp_12_geologie_ns1ns2.sql',12,'Qu''est-ce que la paléomagnétisme et comment a-t-il confirmé l''expansion océanique ?','L''étude du magnétisme fossile des roches','L''étude du magnétisme fossile des roches, montrant des bandes symétriques d''inversions magnétiques de part et d''autre des dorsales, preuve de l''expansion du fond océanique'),
('S0244','v2_supp_12_geologie_ns1ns2.sql',12,'Qu''est-ce que le supercontinent Pangée et quand a-t-il existé ?','Le supercontinent unique regroupant','Le supercontinent unique regroupant toutes les terres émergées actuelles, qui existait il y a environ 300-200 millions d''années avant de se fragmenter'),
('S0245','v2_supp_12_geologie_ns1ns2.sql',12,'Quels sont les trois grands types de roches et comment se forment-ils ?','Ignées (refroidissement du magma)','Ignées (refroidissement du magma), sédimentaires (compaction de sédiments) et métamorphiques (transformation par chaleur/pression)'),
('S0246','v2_supp_12_geologie_ns1ns2.sql',12,'Comment différencie-t-on les roches magmatiques plutoniques des roches volcaniques ?','Les plutoniques (granite) se forment','Les plutoniques (granite) se forment par refroidissement lent en profondeur, formant de grands cristaux ; les volcaniques (basalte) se forment par refroidissement rapide en surface, formant de petits cristaux ou une texture vitreuse'),
('S0247','v2_supp_12_geologie_ns1ns2.sql',12,'Qu''est-ce que le métamorphisme et quels facteurs le contrôlent ?','La transformation de roches','La transformation de roches préexistantes par augmentation de température et/ou pression sans fusion, modifiant la minéralogie et la texture'),
('S0248','v2_supp_12_geologie_ns1ns2.sql',12,'Comment se forment les roches sédimentaires et quel est leur intérêt pour la géologie ?','Par l''accumulation','Par l''accumulation, le compaction et la cimentation de sédiments (détritiques, chimiques ou biochimiques) ; elles contiennent des fossiles et enregistrent l''histoire de la Terre'),
('S0249','v2_supp_12_geologie_ns1ns2.sql',12,'Qu''est-ce que le cycle des roches et quels processus y participent ?','Le cycle géologique dans lequel les','Le cycle géologique dans lequel les roches passent par différents états (magmatique, sédimentaire, métamorphique) via l''érosion, la sédimentation, l''enfouissement, le métamorphisme et la fusion'),
('S0250','v2_supp_12_geologie_ns1ns2.sql',12,'Qu''est-ce que la diagenèse dans la formation des roches sédimentaires ?','L''ensemble des transformations','L''ensemble des transformations physico-chimiques qui transforment des sédiments meubles en roche sédimentaire dure (compaction + cimentation)'),
('S0251','v2_supp_12_geologie_ns1ns2.sql',12,'Qu''est-ce que la minéralogie et quel est le minéral le plus abondant de la croûte terrestre ?','L''étude scientifique des minéraux','L''étude scientifique des minéraux ; les feldspaths sont les minéraux les plus abondants de la croûte (plus de 50%), suivis du quartz'),
('S0252','v2_supp_12_geologie_ns1ns2.sql',12,'Comment la datation radiométrique permet-elle de dater les roches ?','En mesurant le rapport isotope','En mesurant le rapport isotope parent/isotope fils radioactif dans une roche, et en connaissant la demi-vie du radioélement (ex. U-Pb pour les très anciennes roches)'),
('S0253','v2_supp_12_geologie_ns1ns2.sql',12,'Qu''est-ce que le principe de superposition en stratigraphie et qui l''a établi ?','Dans une séquence sédimentaire non','Dans une séquence sédimentaire non perturbée, la couche la plus récente est au sommet et la plus ancienne à la base (Sténon, XVIIe siècle)'),
('S0254','v2_supp_12_geologie_ns1ns2.sql',12,'Qu''est-ce que la géologie haïtienne et quels types de roches y trouve-t-on ?','Haïti présente des roches volcaniques','Haïti présente des roches volcaniques (basaltes), métamorphiques (schistes, quartzites), sédimentaires carbonatées (calcaires) et des intrusions de granite, reflétant son histoire tectonique complexe'),
('S0255','v2_supp_12_geologie_ns3ns4.sql',12,'Quelle est la différence entre le foyer (hypocentre) et l''épicentre d''un séisme ?','Le foyer est le point de rupture dans','Le foyer est le point de rupture dans la croûte où le séisme se déclenche ; l''épicentre est le point en surface directement au-dessus du foyer'),
('S0256','v2_supp_12_geologie_ns3ns4.sql',12,'Quelle est la différence entre l''échelle de Richter et l''échelle de Mercalli ?','Richter (magnitude) mesure l''énergie','Richter (magnitude) mesure l''énergie libérée par le séisme ; Mercalli (intensité) mesure les effets ressentis en un lieu précis'),
('S0257','v2_supp_12_geologie_ns3ns4.sql',12,'Quels sont les deux types principaux d''ondes sismiques et leurs caractéristiques ?','Ondes P (primaires','Ondes P (primaires, longitudinales, traversant tous les milieux) et ondes S (secondaires, transversales, ne traversant pas les liquides)'),
('S0258','v2_supp_12_geologie_ns3ns4.sql',12,'Comment se forme un tsunami et quelles sont les conditions nécessaires ?','Un tremblement de terre sous-marin (ou','Un tremblement de terre sous-marin (ou glissement de terrain) qui déplace verticalement une grande masse d''eau, créant des vagues longues et rapides en haute mer (qui amplifient en approchant des côtes)'),
('S0259','v2_supp_12_geologie_ns3ns4.sql',12,'Qu''est-ce que la liquéfaction des sols lors d''un séisme et pourquoi est-elle dangereuse ?','Le comportement de certains sols','Le comportement de certains sols saturés en eau (sables fins) qui perdent leur résistance lors d''un séisme et se comportent comme un liquide, engloutissant les fondations'),
('S0260','v2_supp_12_geologie_ns3ns4.sql',12,'Quels sont les deux grands types de volcans selon leur structure et leur mode d''éruption ?','Volcans boucliers (basaltiques','Volcans boucliers (basaltiques, coulées fluides, peu explosifs) et stratovolcans (andésitiques/rhyolitiques, explosifs avec pyroclastes et nuées ardentes)'),
('S0261','v2_supp_12_geologie_ns3ns4.sql',12,'Qu''est-ce qu''une nuée ardente et quel est son exemple historique le plus célèbre ?','Un écoulement pyroclastique rapide de','Un écoulement pyroclastique rapide de gaz chauds, cendres et roches (>700°C, >700 km/h) qui ne peut être survécue ; la Montagne Pelée en Martinique (1902, 30 000 morts) en est l''exemple classique'),
('S0262','v2_supp_12_geologie_ns3ns4.sql',12,'Comment se définit le risque sismique et quels sont ses facteurs ?','Le risque sismique = aléa (probabilité','Le risque sismique = aléa (probabilité d''un séisme) × vulnérabilité (qualité des constructions, densité de population) × exposition (valeur des biens et vies exposés)'),
('S0263','v2_supp_12_geologie_ns3ns4.sql',12,'Qu''est-ce que le parc de prévention et les systèmes d''alerte sismique précoce ?','Des réseaux de capteurs sismiques qui','Des réseaux de capteurs sismiques qui détectent les ondes P (plus rapides, moins destructrices) et envoient un avertissement automatique avant l''arrivée des ondes S (destructrices)'),
('S0264','v2_supp_12_geologie_ns3ns4.sql',12,'Qu''est-ce que la sismicité induite et comment les activités humaines peuvent-elles causer des séismes ?','L''injection de fluides en profondeur','L''injection de fluides en profondeur (fracturation hydraulique, stockage CO2, remplissage de barrages) peut modifier les contraintes sur les failles et déclencher des séismes'),
('S0265','v2_supp_12_geologie_ns3ns4.sql',12,'Qu''est-ce que le géorisque en Haïti et comment y faire face ?','Haïti est exposée à des séismes majeurs','Haïti est exposée à des séismes majeurs (failles Enriquillo et Septentrional), des glissements de terrain (déforestation), des tsunamis et des éruptions (à moindre niveau) ; la réduction du risque passe par la réglementation des constructions, la cartographie et l''éducation'),
('S0266','v2_supp_12_geologie_ns3ns4.sql',12,'Qu''est-ce que la construction parasismique et ses principes fondamentaux ?','Construire des bâtiments capables','Construire des bâtiments capables d''absorber l''énergie sismique sans s''effondrer, en utilisant des matériaux flexibles, des fondations isolées et des systèmes d''amortissement'),
('S0267','v2_supp_12_geologie_ns3ns4.sql',12,'Comment se forment les gisements de pétrole et de gaz naturel ?','Par la décomposition de matière','Par la décomposition de matière organique marine (plancton) enfouie sous des sédiments pendant des millions d''années, transformée en hydrocarbures sous l''effet de la chaleur et de la pression'),
('S0268','v2_supp_12_geologie_ns3ns4.sql',12,'Comment se forment les gisements de minerais métalliques ?','Par concentration hydrothermale','Par concentration hydrothermale (circulations de fluides chauds dissolvant les métaux), magmatique (pegmatites) ou sédimentaire (évaporites, bauxite, fer rubané)'),
('S0269','v2_supp_12_geologie_ns3ns4.sql',12,'Quels sont les potentiels miniers d''Haïti selon les études géologiques récentes ?','Des gisements d''or','Des gisements d''or, cuivre et argent (notamment dans le nord, région de Morne Bossa), ainsi que du marbre et des roches ornementales'),
('S0270','v2_supp_12_geologie_ns3ns4.sql',12,'Qu''est-ce que l''énergie géothermique et comment peut-elle être exploitée ?','L''exploitation de la chaleur interne de','L''exploitation de la chaleur interne de la Terre : forages dans des zones à fort gradient géothermique (volcanism), production de vapeur pour générer de l''électricité ou chauffer des bâtiments'),
('S0271','v2_supp_12_geologie_ns3ns4.sql',12,'Qu''est-ce que la géologie environnementale et ses applications ?','L''application de la géologie à la','L''application de la géologie à la résolution de problèmes environnementaux : gestion des aquifères, contamination des sols, choix de sites de déchets, études d''impact'),
('S0272','v2_supp_12_geologie_ns3ns4.sql',12,'Comment la déforestation en Haïti amplifie-t-elle les risques géologiques ?','En enlevant le couvert végétal','En enlevant le couvert végétal, elle accélère l''érosion des sols, augmente les glissements de terrain et les crues soudaines lors des cyclones, et réduit la recharge des nappes phréatiques'),
('S0273','v2_supp_12_geologie_ns3ns4.sql',12,'Qu''est-ce que la gestion durable des ressources minières ?','L''exploitation des ressources minières','L''exploitation des ressources minières en minimisant l''impact environnemental, en restaurant les sites exploités et en assurant que les bénéfices profitent aux communautés locales'),
('S0274','v2_supp_12_geologie_ns3ns4.sql',12,'Qu''est-ce que les aquifères et leur importance en Haïti ?','Des formations géologiques poreuses et','Des formations géologiques poreuses et perméables contenant de l''eau souterraine exploitable ; en Haïti, les aquifères calcaires (karst) dans les plaines sont des sources d''eau potable essentielles'),
('S0275','v2_supp_12_geologie_ns3ns4.sql',12,'Comment les changements climatiques affectent-ils les ressources en eau souterraine ?','En modifiant les régimes de pluie et en','En modifiant les régimes de pluie et en augmentant l''évapotranspiration, les changements climatiques réduisent la recharge des aquifères et augmentent la compétition pour l''eau'),
('S0276','v2_supp_12_geologie_ns3ns4.sql',12,'Qu''est-ce que la télédétection et les SIG (Systèmes d''Information Géographique) en géologie ?','Des outils permettant l''analyse','Des outils permettant l''analyse spatiale des données géologiques : la télédétection (satellites, drones) cartographie les formations géologiques ; les SIG intègrent les données pour la gestion des risques et des ressources'),
('S0277','v2_supp_12_geologie_ns3ns4.sql',12,'Qu''est-ce que la géologie isotopique et ses applications à la géochimie ?','L''étude des rapports isotopiques dans','L''étude des rapports isotopiques dans les minéraux et fluides pour reconstituer les paléoclimats, dater les formations, tracer l''origine des magmas et des fluides hydrothermaux'),
('S0278','v2_supp_12_geologie_ns3ns4.sql',12,'Comment la géologie contribue-t-elle à la compréhension du changement climatique passé et futur ?','Les archives géologiques (carottes de','Les archives géologiques (carottes de glace, sédiments marins, spéléothèmes) enregistrent les paléoclimats sur millions d''années, permettant de calibrer les modèles climatiques et de replacer le réchauffement actuel dans son contexte géologique'),
('S0279','v2_supp_13_histoire_geo_ns1ns2.sql',13,'Entre quels fleuves la Mésopotamie, considérée comme un berceau de la civilisation, est-elle située ?','Tigre et Euphrate','Tigre et Euphrate'),
('S0280','v2_supp_13_histoire_geo_ns1ns2.sql',13,'Quelle est l''une des premières formes d''écriture connue de l''humanité et dans quelle civilisation est-elle apparue ?','Le cunéiforme (écriture à coins) apparu','Le cunéiforme (écriture à coins) apparu à Sumer vers 3500 av. J.-C., utilisé pour les comptes administratifs'),
('S0281','v2_supp_13_histoire_geo_ns1ns2.sql',13,'Qu''est-ce que le Code d''Hammurabi et quelle est son importance historique ?','Un ensemble de 282 lois gravées sur une','Un ensemble de 282 lois gravées sur une stèle babylonienne (~1750 av. J.-C.), l''un des premiers codes juridiques écrits de l''histoire'),
('S0282','v2_supp_13_histoire_geo_ns1ns2.sql',13,'Quel est le rôle du Nil dans la civilisation égyptienne antique ?','La source de fertilité des terres grâce','La source de fertilité des terres grâce à ses crues annuelles déposant du limon, permettant l''agriculture intensive qui nourrissait une grande population et permettait de construire les pyramides'),
('S0283','v2_supp_13_histoire_geo_ns1ns2.sql',13,'Quelle est la signification historique des pyramides de Gizeh ?','Des tombeaux monumentaux des pharaons','Des tombeaux monumentaux des pharaons (Khéops, Khéphren, Mykérinos), manifestations de la puissance divine du pharaon et du développement de l''État centralisé égyptien'),
('S0284','v2_supp_13_histoire_geo_ns1ns2.sql',13,'Qu''est-ce que la démocratie athénienne du Ve siècle av. J.-C. et quelles en étaient les limites ?','Un système où les citoyens libres mâles','Un système où les citoyens libres mâles adultes participaient directement aux décisions ; en excluant les femmes, les esclaves (~1/3 de la pop.) et les étrangers'),
('S0285','v2_supp_13_histoire_geo_ns1ns2.sql',13,'Comment Alexandre le Grand a-t-il transformé le monde méditerranéen entre 336 et 323 av. J.-C. ?','En conquérant un empire s''étendant de','En conquérant un empire s''étendant de la Grèce à l''Inde, diffusant la culture grecque (hellénisme) et créant une civilisation syncrétique gréco-orientale'),
('S0286','v2_supp_13_histoire_geo_ns1ns2.sql',13,'Quelles sont les principales contributions de la civilisation romaine à l''Europe et au monde occidental ?','Le droit romain (base des systèmes','Le droit romain (base des systèmes juridiques modernes), le latin (ancêtre des langues romanes), l''architecture, le réseau routier, le christianisme comme religion d''État'),
('S0287','v2_supp_13_histoire_geo_ns1ns2.sql',13,'Qu''est-ce que la civilisation maya et où s''était-elle développée ?','En Mésoamérique (Guatemala','En Mésoamérique (Guatemala, Mexique, Belize, Honduras), développant une écriture hiéroglyphique, un calendrier astronomique précis, les mathématiques (zéro) et des cités-états monumentales'),
('S0288','v2_supp_13_histoire_geo_ns1ns2.sql',13,'Qu''est-ce que les premiers habitants d''Haïti (les Taïnos) et quelle était leur civilisation ?','Des Amérindiens (sous-groupe Arawak)','Des Amérindiens (sous-groupe Arawak) habitant Hispaniola avant Colomb, organisés en cacicats, pratiquant l''agriculture (manioc, maïs) et une riche vie spirituelle, quasi décimés après 1492'),
('S0289','v2_supp_13_histoire_geo_ns1ns2.sql',13,'Qu''est-ce que la Route de la Soie et son importance dans l''histoire des échanges ?','Un réseau de routes commerciales','Un réseau de routes commerciales reliant la Chine à la Méditerranée (Ier s. av. J.-C. - XVe s. ap. J.-C.), véhiculant soieries, épices mais aussi idées, religions et techniques'),
('S0290','v2_supp_13_histoire_geo_ns1ns2.sql',13,'Quel fut le rôle de Constantinople (Byzance) comme carrefour entre Orient et Occident ?','La capitale de l''Empire byzantin','La capitale de l''Empire byzantin (330-1453), carrefour commercial et culturel entre Europe et Asie, gardienne de la culture grecque et chrétienne orientale jusqu''à la conquête ottomane'),
('S0291','v2_supp_13_histoire_geo_ns1ns2.sql',13,'Quelle date marque le «premier voyage» de Christophe Colomb en Amérique et quelle en a été la conséquence pour Haïti ?','1492','1492, avec l''arrivée à Hispaniola (actuelle Haïti-RD) le 5 décembre, début de la colonisation espagnole et du génocide taïno'),
('S0292','v2_supp_13_histoire_geo_ns1ns2.sql',13,'Qu''est-ce que la traite négrière transatlantique et quel fut son impact sur Haïti ?','Le commerce d''esclaves africains vers','Le commerce d''esclaves africains vers les Amériques (XVIe-XIXe s.) ; Saint-Domingue (Haïti) a reçu ~800 000 à 1 million d''Africains, devenant la colonie esclavagiste la plus productive du monde'),
('S0293','v2_supp_13_histoire_geo_ns1ns2.sql',13,'Quelle est la signification de la Révolution américaine (1775-1783) dans l''histoire mondiale ?','La première révolution des colonies','La première révolution des colonies contre une métropole européenne, instaurant la première démocratie constitutionnelle moderne, et inspirant les révolutions française et haïtienne'),
('S0294','v2_supp_13_histoire_geo_ns1ns2.sql',13,'Quelles sont les causes et les principales phases de la Révolution française (1789) ?','Les inégalités fiscales et sociales de','Les inégalités fiscales et sociales de l''Ancien Régime, la crise financière et les Lumières ont déclenché la Révolution ; phases : Monarchie constitutionnelle, Convention (Terreur), Directoire, Empire'),
('S0295','v2_supp_13_histoire_geo_ns1ns2.sql',13,'Quel est le rôle de Toussaint Louverture dans la révolution haïtienne ?','L''ex-esclave devenu chef militaire','L''ex-esclave devenu chef militaire exceptionnel qui a réuni les esclaves, vaincu les armées espagnole, anglaise et française, et rédigé la première Constitution haïtienne (1801) qui abolissait l''esclavage'),
('S0296','v2_supp_13_histoire_geo_ns1ns2.sql',13,'Quelle est la signification de la Bataille de Vertières (18 novembre 1803) dans l''histoire haïtienne ?','La dernière grande bataille de la','La dernière grande bataille de la révolution haïtienne, où les forces de Jean-Jacques Dessalines ont vaincu l''armée napoléonienne, ouvrant la voie à l''indépendance'),
('S0297','v2_supp_13_histoire_geo_ns1ns2.sql',13,'Pourquoi la révolution haïtienne de 1804 est-elle unique dans l''histoire mondiale ?','C''est la seule révolution d''esclaves','C''est la seule révolution d''esclaves réussie de l''histoire ayant abouti à la création d''un État indépendant (première République noire du monde et deuxième des Amériques)'),
('S0298','v2_supp_13_histoire_geo_ns1ns2.sql',13,'Qu''est-ce que la Révolution industrielle (XVIIIe-XIXe siècle) et où a-t-elle débuté ?','La transformation économique débutée en','La transformation économique débutée en Angleterre basée sur la mécanisation (machine à vapeur de Watt), la production en usine, l''exploitation du charbon et de l''acier'),
('S0299','v2_supp_13_histoire_geo_ns1ns2.sql',13,'Qu''est-ce que le colonialisme européen du XIXe siècle et ses justifications idéologiques ?','L''expansion territoriale des puissances','L''expansion territoriale des puissances européennes en Afrique et en Asie, justifiée par la «mission civilisatrice», le racisme scientifique et les intérêts économiques (matières premières, marchés)'),
('S0300','v2_supp_13_histoire_geo_ns1ns2.sql',13,'Qu''est-ce que la dette de l''indépendance haïtienne de 1825 et ses conséquences à long terme ?','Le paiement imposé par la France à','Le paiement imposé par la France à Haïti (150 millions de francs-or) pour reconnaître l''indépendance, remboursé jusqu''en 1947, qui a appauvri le pays pendant plus d''un siècle'),
('S0301','v2_supp_13_histoire_geo_ns1ns2.sql',13,'Qu''est-ce que les guerres napoléoniennes et leur impact sur l''Europe et le monde ?','Les guerres menées par Napoléon','Les guerres menées par Napoléon Bonaparte (1803-1815) qui ont reconfiguré la carte de l''Europe, diffusé les principes révolutionnaires français (Code civil) et déclenché des nationalismes dans les territoires occupés'),
('S0302','v2_supp_13_histoire_geo_ns3ns4.sql',13,'Quelles sont les principales causes de la Première Guerre mondiale (1914-1918) ?','Un faisceau de causes','Un faisceau de causes : impérialisme, nationalisme, militarisme, systèmes d''alliances rigides (Triple Entente vs Triple Alliance), déclenchées par l''assassinat de Franz Ferdinand à Sarajevo'),
('S0303','v2_supp_13_histoire_geo_ns3ns4.sql',13,'Quelles sont les conséquences du Traité de Versailles (1919) sur l''Allemagne et le monde ?','Des conditions humiliantes (clause de','Des conditions humiliantes (clause de culpabilité, reparations de 132 milliards de marks-or, pertes territoriales) qui ont contribué à l''instabilité de la République de Weimar et à la montée du nazisme'),
('S0304','v2_supp_13_histoire_geo_ns3ns4.sql',13,'Qu''est-ce que la Shoah (Holocauste) et combien de victimes a-t-elle causées ?','Le génocide systématique des Juifs','Le génocide systématique des Juifs d''Europe par les nazis, faisant environ 6 millions de victimes (60% des Juifs européens), dans des camps d''extermination'),
('S0305','v2_supp_13_histoire_geo_ns3ns4.sql',13,'Quelles sont les principales causes de la Deuxième Guerre mondiale ?','Le traité humiliant de Versailles','Le traité humiliant de Versailles, la Grande Dépression (1929), la montée des fascismes (Hitler, Mussolini), la politique d''apaisement d''Appeasement et l''invasion de la Pologne (1939)'),
('S0306','v2_supp_13_histoire_geo_ns3ns4.sql',13,'Quel est le rôle de la bombe atomique dans la fin de la Seconde Guerre mondiale ?','Les bombes d''Hiroshima (6 août 1945) et','Les bombes d''Hiroshima (6 août 1945) et Nagasaki (9 août 1945) ont provoqué la capitulation du Japon, introduisant l''ère nucléaire et soulevant des questions éthiques permanentes sur l''usage des armes de destruction massive'),
('S0307','v2_supp_13_histoire_geo_ns3ns4.sql',13,'Qu''est-ce que l''ONU et pourquoi a-t-elle été créée en 1945 ?','Une organisation internationale créée','Une organisation internationale créée après la WWII pour maintenir la paix, prévenir un nouveau génocide et favoriser la coopération internationale, succédant à la Société des Nations'),
('S0308','v2_supp_13_histoire_geo_ns3ns4.sql',13,'Qu''est-ce que la décolonisation et comment s''est-elle déroulée après 1945 ?','Le processus d''accession à','Le processus d''accession à l''indépendance des colonies asiatiques et africaines (1945-1975), parfois négocié (Inde 1947), parfois violent (Algérie, Angola), soulevant des questions d''identité et de développement'),
('S0309','v2_supp_13_histoire_geo_ns3ns4.sql',13,'Qu''est-ce que la Guerre froide et quels en ont été les principaux moments de crise ?','L''affrontement idéologique et','L''affrontement idéologique et géopolitique entre les États-Unis (bloc occidental libéral) et l''URSS (bloc communiste) de 1947 à 1991, avec des crises majeures : Berlin (1961), Cuba (1962), Vietnam (1965-75)'),
('S0310','v2_supp_13_histoire_geo_ns3ns4.sql',13,'Quelle a été la relation entre Haïti et les États-Unis au XXe siècle, notamment l''occupation américaine ?','L''occupation américaine d''Haïti','L''occupation américaine d''Haïti (1915-1934) a modernisé certaines infrastructures mais aussi humilié la souveraineté haïtienne, et les interventions constantes ont influencé la politique haïtienne tout au long du XXe siècle'),
('S0311','v2_supp_13_histoire_geo_ns3ns4.sql',13,'Quel a été le règne des Duvalier et son impact sur Haïti ?','Une dictature familiale (François','Une dictature familiale (François Duvalier «Papa Doc» 1957-1971, puis Jean-Claude «Baby Doc» 1971-1986) caractérisée par la terreur des Tontons Macoutes, la répression, la corruption et une émigration massive'),
('S0312','v2_supp_13_histoire_geo_ns3ns4.sql',13,'Quelle est la signification de la révolution cubaine de 1959 pour les Caraïbes et l''Amérique latine ?','Le renversement de Batista par Castro a','Le renversement de Batista par Castro a instauré le premier régime communiste des Amériques, provoquant la crise de Cuba (1962), exacerbant les tensions de la Guerre froide dans les Caraïbes et inspirant des guérillas en Amérique latine'),
('S0313','v2_supp_13_histoire_geo_ns3ns4.sql',13,'Qu''est-ce que la Conférence de Bandung (1955) et le mouvement des Non-Alignés ?','La conférence de 29 pays','La conférence de 29 pays afro-asiatiques déclarant leur refus de s''aligner sur les deux blocs (USA/URSS), cherchant une «troisième voie» ; mouvement fondé sur la souveraineté, l''anti-colonialisme et la solidarité Sud-Sud'),
('S0314','v2_supp_13_histoire_geo_ns3ns4.sql',13,'Qu''est-ce que la mondialisation et quelles en sont les dimensions principales ?','L''intensification des échanges','L''intensification des échanges économiques (commerce, investissements, chaînes de valeur), des flux d''informations et des migrations humaines à l''échelle planétaire, avec des effets inégaux selon les régions'),
('S0315','v2_supp_13_histoire_geo_ns3ns4.sql',13,'Quel est le rôle des organisations économiques internationales (FMI, Banque mondiale, OMC) ?','Des institutions de gouvernance','Des institutions de gouvernance économique mondiale : le FMI gère les crises financières, la Banque mondiale finance le développement, l''OMC régule le commerce international'),
('S0316','v2_supp_13_histoire_geo_ns3ns4.sql',13,'Qu''est-ce que la géopolitique des ressources naturelles et comment structure-t-elle les relations internationales ?','Le contrôle des ressources (pétrole','Le contrôle des ressources (pétrole, eau, terres rares) structure les alliances, les conflits et les inégalités mondiales ; les pays producteurs subissent souvent la «malédiction des ressources»'),
('S0317','v2_supp_13_histoire_geo_ns3ns4.sql',13,'Qu''est-ce que l''émergence des pays BRICS et leur impact sur l''ordre mondial ?','L''essor du Brésil','L''essor du Brésil, de la Russie, de l''Inde, de la Chine et de l''Afrique du Sud (BRICS) qui contestent l''hégémonie occidentale, proposent des alternatives aux institutions de Bretton Woods et redessinent les équilibres géopolitiques'),
('S0318','v2_supp_13_histoire_geo_ns3ns4.sql',13,'Qu''est-ce que le changement climatique comme enjeu géopolitique majeur du XXIe siècle ?','Un enjeu qui menace la sécurité des','Un enjeu qui menace la sécurité des États (migrations climatiques, conflits pour l''eau), recompose les alliances et oppose pays industrialisés (émetteurs historiques) et pays vulnérables (dont Haïti) sur la question de la responsabilité et de l''aide'),
('S0319','v2_supp_13_histoire_geo_ns3ns4.sql',13,'Qu''est-ce que la Communauté des Caraïbes (CARICOM) et quel est son rôle pour Haïti ?','Une organisation régionale','Une organisation régionale d''intégration économique et politique des Caraïbes, dont Haïti est membre ; elle promeut le commerce intrazone, la libre circulation et la coordination des politiques'),
('S0320','v2_supp_13_histoire_geo_ns3ns4.sql',13,'Qu''est-ce que la question de la migration internationale et ses enjeux pour Haïti ?','La diaspora haïtienne (~2 millions de','La diaspora haïtienne (~2 millions de personnes aux USA, Canada, France, RD, Bahamas) représente un apport économique vital (transferts ~>3 milliards $/an) mais aussi un drain des cerveaux'),
('S0321','v2_supp_13_histoire_geo_ns3ns4.sql',13,'Comment comprendre les relations haïtiano-dominicaines dans un contexte géopolitique régional ?','Des relations complexes sur une île','Des relations complexes sur une île partagée : interdépendance économique (commerce, main-d''œuvre), tensions historiques (massacre de 1937, Trujillo) et enjeux actuels de migration et d''apatridie'),
('S0322','v2_supp_13_histoire_geo_ns3ns4.sql',13,'Qu''est-ce que la communauté internationale et l''aide au développement : le cas d''Haïti ?','L''aide internationale à Haïti','L''aide internationale à Haïti (~500M$/an avant 2010) a souvent renforcé la dépendance, contourné l''État haïtien et profité aux ONG étrangères plus qu''aux institutions locales, un phénomène critiqué comme «business humanitaire»'),
('S0323','v2_supp_13_histoire_geo_ns3ns4.sql',13,'Qu''est-ce que la gouvernance mondiale et ses défis actuels ?','L''ensemble des institutions','L''ensemble des institutions, règles et processus par lesquels la communauté internationale gère les problèmes collectifs (changement climatique, pandémies, cyberguerre) en l''absence d''un gouvernement mondial'),
('S0324','v2_supp_13_histoire_geo_ns3ns4.sql',13,'Comment la géographie physique d''Haïti influence-t-elle sa vulnérabilité aux catastrophes naturelles ?','Sa position dans la zone sismique des','Sa position dans la zone sismique des Caraïbes, son relief montagneux accidenté, sa déforestation avancée et sa géographie côtière exposée aux cyclones se combinent pour en faire l''un des pays les plus vulnérables du monde'),
('S0325','v2_supp_13_histoire_geo_ns3ns4.sql',13,'Quel est le mouvement mondial des droits de l''homme depuis 1948 et ses avancées et limites ?','La DUDH (1948) a établi des standards','La DUDH (1948) a établi des standards universels ; des progrès réels ont été faits (abolition de l''apartheid, tribunaux pénaux internationaux) mais des violations persistent partout, soulignant la tension entre souveraineté des États et universalité des droits'),
('S0326','v2_supp_15_economie_ns1ns2.sql',15,'Quel est le problème économique fondamental qui justifie l''existence de l''économie ?','La rareté des ressources face à des','La rareté des ressources face à des besoins illimités'),
('S0327','v2_supp_15_economie_ns1ns2.sql',15,'Qu''est-ce que le coût d''opportunité ?','La valeur de la meilleure alternative','La valeur de la meilleure alternative sacrifiée lors d''un choix'),
('S0328','v2_supp_15_economie_ns1ns2.sql',15,'Quelle est la différence entre besoin et désir en économie ?','Le besoin est vital/essentiel','Le besoin est vital/essentiel, le désir est une préférence non nécessaire'),
('S0329','v2_supp_15_economie_ns1ns2.sql',15,'Qu''est-ce qu''un bien économique ?','Tout bien ou service rare ayant une','Tout bien ou service rare ayant une valeur économique et satisfaisant un besoin'),
('S0330','v2_supp_15_economie_ns1ns2.sql',15,'Que représente la courbe de possibilités de production (CPP) ?','Les combinaisons maximales de deux','Les combinaisons maximales de deux biens qu''une économie peut produire'),
('S0331','v2_supp_15_economie_ns1ns2.sql',15,'Quelle est la différence entre microéconomie et macroéconomie ?','Micro = comportements','Micro = comportements individuels/marchés, Macro = économie globale (PIB, chômage, inflation)'),
('S0332','v2_supp_15_economie_ns1ns2.sql',15,'Qu''est-ce qu''un facteur de production ?','Une ressource utilisée pour produire','Une ressource utilisée pour produire des biens et services (terre, travail, capital)'),
('S0333','v2_supp_15_economie_ns1ns2.sql',15,'Qu''est-ce que l''utilité marginale ?','Le gain de satisfaction procuré par une','Le gain de satisfaction procuré par une unité supplémentaire consommée'),
('S0334','v2_supp_15_economie_ns1ns2.sql',15,'Quel est le rôle du signal prix dans une économie de marché ?','Transmettre l''information sur la rareté','Transmettre l''information sur la rareté et coordonner les décisions des agents'),
('S0335','v2_supp_15_economie_ns1ns2.sql',15,'Qu''est-ce qu''une externalité en économie ?','Un effet (positif ou négatif) d''une','Un effet (positif ou négatif) d''une activité économique sur des tiers non impliqués dans la transaction'),
('S0336','v2_supp_15_economie_ns1ns2.sql',15,'Qu''est-ce que la loi des rendements décroissants ?','Au-delà d''un certain niveau','Au-delà d''un certain niveau, ajouter un facteur variable diminue le rendement marginal'),
('S0337','v2_supp_15_economie_ns1ns2.sql',15,'Qu''est-ce que l''avantage comparatif dans le commerce international ?','Produire à un coût d''opportunité','Produire à un coût d''opportunité relatif inférieur, même sans avantage absolu'),
('S0338','v2_supp_15_economie_ns1ns2.sql',15,'Qu''est-ce que la valeur d''usage et la valeur d''échange selon Marx ?','Usage = utilité pour le possesseur','Usage = utilité pour le possesseur, échange = quantité de travail social incorporé'),
('S0339','v2_supp_15_economie_ns1ns2.sql',15,'Que se passe-t-il sur la demande quand le prix d''un bien augmente (toutes choses égales) ?','La demande diminue','La demande diminue'),
('S0340','v2_supp_15_economie_ns1ns2.sql',15,'Que représente l''élasticité-prix de la demande ?','La sensibilité de la quantité demandée','La sensibilité de la quantité demandée à une variation de prix'),
('S0341','v2_supp_15_economie_ns1ns2.sql',15,'Qu''est-ce qu''un bien de Giffen ?','Un bien inférieur dont la demande','Un bien inférieur dont la demande augmente quand son prix monte (paradoxe)'),
('S0342','v2_supp_15_economie_ns1ns2.sql',15,'Qu''est-ce qu''un bien substituable ?','Un bien pouvant remplacer un autre','Un bien pouvant remplacer un autre (ex : beurre et margarine)'),
('S0343','v2_supp_15_economie_ns1ns2.sql',15,'Quel est le prix d''équilibre sur un marché concurrentiel ?','Le prix où la quantité offerte est','Le prix où la quantité offerte est égale à la quantité demandée'),
('S0344','v2_supp_15_economie_ns1ns2.sql',15,'Qu''est-ce qu''un surplus du consommateur ?','La différence entre ce qu''un','La différence entre ce qu''un consommateur est prêt à payer et ce qu''il paie réellement'),
('S0345','v2_supp_15_economie_ns1ns2.sql',15,'Que provoque un prix plancher (prix minimum légal) supérieur au prix d''équilibre ?','Un surplus (excédent d''offre)','Un surplus (excédent d''offre)'),
('S0346','v2_supp_15_economie_ns1ns2.sql',15,'Qu''est-ce que la concurrence parfaite ?','Un marché avec de nombreux acheteurs et','Un marché avec de nombreux acheteurs et vendeurs, produits homogènes, information parfaite, libre entrée'),
('S0347','v2_supp_15_economie_ns1ns2.sql',15,'Qu''est-ce qu''une défaillance de marché ?','Une situation où le marché libre','Une situation où le marché libre n''alloue pas les ressources de façon optimale'),
('S0348','v2_supp_15_economie_ns1ns2.sql',15,'Qu''est-ce qu''un bien public au sens économique ?','Un bien non rival et non excluable','Un bien non rival et non excluable (ex : défense nationale, phare)'),
('S0349','v2_supp_15_economie_ns1ns2.sql',15,'Qu''est-ce que l''asymétrie d''information ?','Quand une partie dispose de plus','Quand une partie dispose de plus d''informations que l''autre (ex : vendeur de voitures d''occasion)'),
('S0350','v2_supp_15_economie_ns1ns2.sql',15,'Qu''est-ce qu''un monopole naturel ?','Un marché où une seule entreprise peut','Un marché où une seule entreprise peut desservir le marché à moindre coût (ex : réseau ferroviaire)'),
('S0351','v2_supp_15_economie_ns1ns2.sql',15,'Quel est l''effet d''une subvention sur l''offre d''un bien ?','Elle augmente l''offre et baisse le prix','Elle augmente l''offre et baisse le prix de marché'),
('S0352','v2_supp_15_economie_ns1ns2.sql',15,'Quelles sont les trois fonctions classiques de la monnaie ?','Intermédiaire des échanges','Intermédiaire des échanges, unité de compte, réserve de valeur'),
('S0353','v2_supp_15_economie_ns1ns2.sql',15,'Qu''est-ce que la masse monétaire M1 ?','Les billets, pièces et dépôts à vue','Les billets, pièces et dépôts à vue (disponibles immédiatement)'),
('S0354','v2_supp_15_economie_ns1ns2.sql',15,'Quel est le rôle principal d''une banque centrale ?','Réguler la politique monétaire','Réguler la politique monétaire (émission, taux directeurs, stabilité des prix)'),
('S0355','v2_supp_15_economie_ns1ns2.sql',15,'Qu''est-ce que l''inflation ?','Une hausse générale et durable du','Une hausse générale et durable du niveau des prix'),
('S0356','v2_supp_15_economie_ns1ns2.sql',15,'Qu''est-ce que le taux directeur d''une banque centrale ?','Le taux auquel la banque centrale prête','Le taux auquel la banque centrale prête aux banques commerciales'),
('S0357','v2_supp_15_economie_ns1ns2.sql',15,'Qu''est-ce que la création monétaire par les banques commerciales ?','Octroyer des crédits qui créent des','Octroyer des crédits qui créent des dépôts ("les crédits font les dépôts")'),
('S0358','v2_supp_15_economie_ns1ns2.sql',15,'Qu''est-ce que le taux de change ?','Le prix d''une monnaie exprimé en une','Le prix d''une monnaie exprimé en une autre monnaie'),
('S0359','v2_supp_15_economie_ns1ns2.sql',15,'Qu''est-ce qu''une bulle spéculative ?','Une hausse excessive des prix d''actifs','Une hausse excessive des prix d''actifs déconnectée de leur valeur fondamentale'),
('S0360','v2_supp_15_economie_ns1ns2.sql',15,'Quel instrument financier représente une part de propriété dans une entreprise ?','Une action','Une action'),
('S0361','v2_supp_15_economie_ns1ns2.sql',15,'Qu''est-ce que la politique monétaire expansionniste ?','Abaisser les taux d''intérêt et','Abaisser les taux d''intérêt et accroître la masse monétaire pour stimuler l''économie'),
('S0362','v2_supp_15_economie_ns1ns2.sql',15,'Qu''est-ce que la stagflation ?','La coexistence d''inflation et de','La coexistence d''inflation et de stagnation économique (chômage élevé)'),
('S0363','v2_supp_15_economie_ns1ns2.sql',15,'Qu''est-ce que le risque systémique dans le système financier ?','Le risque qu''une défaillance locale se','Le risque qu''une défaillance locale se propage à tout le système financier'),
('S0364','v2_supp_15_economie_ns1ns2.sql',15,'Qu''est-ce que le PIB (Produit Intérieur Brut) ?','La valeur totale des biens et services','La valeur totale des biens et services produits dans un pays sur une période'),
('S0365','v2_supp_15_economie_ns1ns2.sql',15,'Quels sont les facteurs classiques de la croissance économique selon Solow ?','Accumulation du capital','Accumulation du capital, croissance de la main-d''œuvre et progrès technique'),
('S0366','v2_supp_15_economie_ns1ns2.sql',15,'Qu''est-ce que le développement durable ?','Un développement qui satisfait les','Un développement qui satisfait les besoins du présent sans compromettre ceux des générations futures'),
('S0367','v2_supp_15_economie_ns1ns2.sql',15,'Qu''est-ce que le capital humain ?','Les compétences','Les compétences, connaissances et santé des travailleurs acquises par l''éducation et la formation'),
('S0368','v2_supp_15_economie_ns1ns2.sql',15,'Qu''est-ce qu''une récession économique ?','Deux trimestres consécutifs de','Deux trimestres consécutifs de croissance négative du PIB'),
('S0369','v2_supp_15_economie_ns1ns2.sql',15,'Qu''est-ce que l''Indice de Développement Humain (IDH) mesure ?','Une mesure composite de l''espérance de','Une mesure composite de l''espérance de vie, de l''éducation et du revenu'),
('S0370','v2_supp_15_economie_ns1ns2.sql',15,'Qu''est-ce que la "destruction créatrice" selon Schumpeter ?','Le processus par lequel l''innovation','Le processus par lequel l''innovation détruit les vieilles industries pour en créer de nouvelles'),
('S0371','v2_supp_15_economie_ns1ns2.sql',15,'Qu''est-ce que le multiplicateur keynésien ?','Une augmentation des dépenses qui','Une augmentation des dépenses qui entraîne une hausse du revenu supérieure à l''injection initiale'),
('S0372','v2_supp_15_economie_ns1ns2.sql',15,'Qu''est-ce que la convergence économique en économie du développement ?','Les pays pauvres tendent à croître plus','Les pays pauvres tendent à croître plus vite que les riches pour réduire l''écart'),
('S0373','v2_supp_15_economie_ns1ns2.sql',15,'Que mesure le coefficient de Gini ?','Le degré d''inégalité dans la','Le degré d''inégalité dans la distribution des revenus (0 = égalité parfaite, 1 = inégalité totale)'),
('S0374','v2_supp_15_economie_ns1ns2.sql',15,'Qu''est-ce que la politique budgétaire contra-cyclique ?','Augmenter les dépenses en période de','Augmenter les dépenses en période de récession et réduire en période de croissance forte'),
('S0375','v2_supp_15_economie_ns1ns2.sql',15,'Qu''est-ce que le commerce intra-branche ?','Échange de biens du même secteur entre','Échange de biens du même secteur entre pays de niveau de développement similaire'),
('S0376','v2_supp_15_economie_ns3ns4.sql',15,'Quel est le théorème HOS (Heckscher-Ohlin-Samuelson) sur le commerce international ?','Chaque pays se spécialise dans les','Chaque pays se spécialise dans les biens intensifs en son facteur de production abondant'),
('S0377','v2_supp_15_economie_ns3ns4.sql',15,'Qu''est-ce qu''un tarif douanier et son effet ?','Une taxe sur les importations qui','Une taxe sur les importations qui augmente leur prix et protège les producteurs locaux'),
('S0378','v2_supp_15_economie_ns3ns4.sql',15,'Qu''est-ce qu''un quota d''importation ?','Une limite quantitative sur les','Une limite quantitative sur les importations d''un bien'),
('S0379','v2_supp_15_economie_ns3ns4.sql',15,'Qu''est-ce que la balance commerciale ?','La différence entre exportations et','La différence entre exportations et importations de biens'),
('S0380','v2_supp_15_economie_ns3ns4.sql',15,'Quel organisme régule le commerce international depuis 1995 ?','OMC (Organisation Mondiale du Commerce)','OMC (Organisation Mondiale du Commerce)'),
('S0381','v2_supp_15_economie_ns3ns4.sql',15,'Qu''est-ce que le dumping dans le commerce international ?','Vendre un bien à l''étranger en dessous','Vendre un bien à l''étranger en dessous de son coût de production pour conquérir des parts de marché'),
('S0382','v2_supp_15_economie_ns3ns4.sql',15,'Qu''est-ce que la balance des paiements ?','Le document qui enregistre toutes les','Le document qui enregistre toutes les transactions économiques d''un pays avec le reste du monde'),
('S0383','v2_supp_15_economie_ns3ns4.sql',15,'Quel est le paradoxe de Leontief ?','Les États-Unis exportent des biens','Les États-Unis exportent des biens capital-intensifs alors qu''ils sont le pays le plus capitalisé'),
('S0384','v2_supp_15_economie_ns3ns4.sql',15,'Qu''est-ce que la globalisation financière ?','L''intégration croissante des marchés','L''intégration croissante des marchés financiers mondiaux et la libre circulation des capitaux'),
('S0385','v2_supp_15_economie_ns3ns4.sql',15,'Qu''est-ce que la "triade" dans le commerce mondial ?','Les États-Unis','Les États-Unis, l''Europe et le Japon qui dominaient le commerce mondial dans les années 1990'),
('S0386','v2_supp_15_economie_ns3ns4.sql',15,'Quel est l''argument de l''industrie naissante pour le protectionnisme ?','Protéger temporairement une nouvelle','Protéger temporairement une nouvelle industrie jusqu''à ce qu''elle atteigne des économies d''échelle compétitives'),
('S0387','v2_supp_15_economie_ns3ns4.sql',15,'Qu''est-ce que la "maladie hollandaise" ?','La désindustrialisation causée par','La désindustrialisation causée par l''appréciation de la monnaie suite à une ressource naturelle abondante'),
('S0388','v2_supp_15_economie_ns3ns4.sql',15,'Qu''est-ce qu''une zone de libre-échange ?','Un accord entre pays supprimant les','Un accord entre pays supprimant les barrières commerciales entre membres, chacun gardant sa politique vis-à-vis des tiers'),
('S0389','v2_supp_15_economie_ns3ns4.sql',15,'Qu''est-ce que le chômage frictionnel ?','Le chômage temporaire lié à la','Le chômage temporaire lié à la transition entre emplois'),
('S0390','v2_supp_15_economie_ns3ns4.sql',15,'Qu''est-ce que la courbe de Phillips originale (années 1960) établit ?','Une relation inverse entre inflation et','Une relation inverse entre inflation et chômage'),
('S0391','v2_supp_15_economie_ns3ns4.sql',15,'Qu''est-ce que le taux de chômage naturel (NAIRU) ?','Le taux de chômage compatible avec une','Le taux de chômage compatible avec une inflation stable (ni accélérante ni décélérante)'),
('S0392','v2_supp_15_economie_ns3ns4.sql',15,'Qu''est-ce que la politique budgétaire ?','L''utilisation des dépenses publiques et','L''utilisation des dépenses publiques et de la fiscalité pour influencer l''activité économique'),
('S0393','v2_supp_15_economie_ns3ns4.sql',15,'Qu''est-ce que le déficit public ?','L''excès des dépenses publiques sur les','L''excès des dépenses publiques sur les recettes fiscales en une année'),
('S0394','v2_supp_15_economie_ns3ns4.sql',15,'Qu''est-ce que l''austérité budgétaire et ses effets débattus ?','Réduction du déficit par coupes dans','Réduction du déficit par coupes dans les dépenses ou hausses d''impôts, pouvant réduire la croissance à court terme'),
('S0395','v2_supp_15_economie_ns3ns4.sql',15,'Qu''est-ce que le quantitative easing (QE) ?','Des achats d''actifs par la banque','Des achats d''actifs par la banque centrale pour injecter des liquidités dans l''économie'),
('S0396','v2_supp_15_economie_ns3ns4.sql',15,'Qu''est-ce que la trappe à liquidité (Keynes) ?','Une situation où la politique monétaire','Une situation où la politique monétaire devient inefficace car les taux sont proches de zéro'),
('S0397','v2_supp_15_economie_ns3ns4.sql',15,'Qu''est-ce que la règle de Taylor en politique monétaire ?','Une règle prescrivant le taux directeur','Une règle prescrivant le taux directeur optimal en fonction de l''inflation et de l''output gap'),
('S0398','v2_supp_15_economie_ns3ns4.sql',15,'Qu''est-ce que l''effet d''éviction en politique budgétaire ?','Des dépenses publiques financées par','Des dépenses publiques financées par emprunt qui font monter les taux et réduisent l''investissement privé'),
('S0399','v2_supp_15_economie_ns3ns4.sql',15,'Qu''est-ce que la théorie quantitative de la monnaie (MV = PQ) ?','La relation entre masse monétaire (M)','La relation entre masse monétaire (M), vitesse (V), niveau des prix (P) et production (Q)'),
('S0400','v2_supp_15_economie_ns3ns4.sql',15,'Qu''est-ce que le paradoxe de l''épargne (Keynes) ?','Ce qui est raisonnable pour un ménage','Ce qui est raisonnable pour un ménage (épargner plus) peut nuire à l''économie si tout le monde le fait'),
('S0401','v2_supp_15_economie_ns3ns4.sql',15,'Qu''est-ce que le "taper tantrum" et quel risque illustre-t-il ?','La volatilité des marchés émergents','La volatilité des marchés émergents quand la Fed signale un durcissement de sa politique monétaire'),
('S0402','v2_supp_15_economie_ns3ns4.sql',15,'Quels sont les principaux indicateurs de la pauvreté selon la Banque Mondiale ?','Pauvreté monétaire (seuil < 2','Pauvreté monétaire (seuil < 2,15$/jour), IDH, taux de malnutrition, accès aux services'),
('S0403','v2_supp_15_economie_ns3ns4.sql',15,'Qu''est-ce que le cercle vicieux de la pauvreté (Nurkse) ?','Faible revenu → faible épargne → faible','Faible revenu → faible épargne → faible investissement → faible productivité → faible revenu'),
('S0404','v2_supp_15_economie_ns3ns4.sql',15,'Quel rôle jouent les transferts de la diaspora pour les économies comme Haïti ?','Principal flux de revenus extérieurs','Principal flux de revenus extérieurs, dépassant souvent l''aide publique au développement'),
('S0405','v2_supp_15_economie_ns3ns4.sql',15,'Qu''est-ce que le "dutch disease" (maladie hollandaise) appliqué aux pays pétroliers ?','L''appréciation de la monnaie et la','L''appréciation de la monnaie et la désindustrialisation causées par les revenus pétroliers'),
('S0406','v2_supp_15_economie_ns3ns4.sql',15,'Qu''est-ce que l''ajustement structurel imposé par le FMI aux pays en développement ?','Des réformes libérales conditionnant','Des réformes libérales conditionnant les prêts : privatisations, déréglementation, coupes budgétaires'),
('S0407','v2_supp_15_economie_ns3ns4.sql',15,'Qu''est-ce que l''économie informelle dans les pays en développement ?','L''ensemble des activités économiques','L''ensemble des activités économiques non déclarées, non régulées, hors du cadre légal formel'),
('S0408','v2_supp_15_economie_ns3ns4.sql',15,'Quel est l''impact du séisme de 2010 sur l''économie haïtienne ?','Une destruction d''une part considérable','Une destruction d''une part considérable du PIB, des infrastructures et du capital humain'),
('S0409','v2_supp_15_economie_ns3ns4.sql',15,'Qu''est-ce que la microfinance comme outil de développement ?','Des services financiers (microcrédit','Des services financiers (microcrédit, épargne) destinés aux populations exclues du système bancaire traditionnel'),
('S0410','v2_supp_15_economie_ns3ns4.sql',15,'Qu''est-ce que le "big push" en économie du développement (Rosenstein-Rodan) ?','L''idée qu''un investissement massif et','L''idée qu''un investissement massif et coordonné est nécessaire pour sortir d''un équilibre de faible croissance'),
('S0411','v2_supp_15_economie_ns3ns4.sql',15,'Qu''est-ce que la dépendance au sentier (path dependency) appliquée aux économies ? ','Les choix passés (institutions','Les choix passés (institutions, technologies) contraignent les options futures même si de meilleures existent'),
('S0412','v2_supp_15_economie_ns3ns4.sql',15,'Qu''est-ce que le consensus de Washington et ses critiques ?','Un ensemble de politiques libérales','Un ensemble de politiques libérales (privatisation, ouverture) prescrit aux PED, critiqué pour ignorer le contexte local'),
('S0413','v2_supp_15_economie_ns3ns4.sql',15,'Qu''est-ce que la trappe à conflits (Paul Collier) et comment affecte-t-elle les PED ?','La tendance des pays pauvres et','La tendance des pays pauvres et fragiles à entrer dans des cycles de violence qui perpétuent la pauvreté'),
('S0414','v2_supp_15_economie_ns3ns4.sql',15,'Quel est le rôle des institutions dans le développement économique selon North et Acemoglu ?','Les institutions inclusives créent les','Les institutions inclusives créent les incitations nécessaires à l''investissement et à l''innovation'),
('S0415','v2_supp_16_philosophie_ns1ns2.sql',16,'Quel philosophe grec est considéré comme le père de la philosophie occidentale ?','Socrate','Socrate'),
