('S0454','v2_supp_16_philosophie_ns1ns2.sql',16,'Qu''est-ce que la correspondance comme théorie de la vérité ?','Une proposition est vraie si elle','Une proposition est vraie si elle correspond à la réalité'),
('S0455','v2_supp_16_philosophie_ns1ns2.sql',16,'Qu''est-ce que le rationalisme critique de Karl Popper ?','Toute théorie scientifique doit être','Toute théorie scientifique doit être réfutable (falsifiable)'),
