('S0474','v2_supp_16_philosophie_ns1ns2.sql',16,'Quel philosophe a développé la notion de "justice comme équité" ?','Rawls','Rawls'),
('S0475','v2_supp_16_philosophie_ns1ns2.sql',16,'Quel philosophe a théorisé la séparation des pouvoirs ?','Montesquieu','Montesquieu'),
