('S1123','v2_supp_27_mathematiques_ns1ns2.sql',27,'Que représente ∫ₐᵇ f(x) dx géométriquement pour f(x) ≥ 0 ?','L''aire sous la courbe entre x=a et x=b','L''aire sous la courbe entre x=a et x=b'),
